INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35296, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「決めた」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」では「決めた」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、「決める」の目的語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を示し、ここでは非文になる。"}], "correct_answer": "を", "explanations": {"を": "「決めた」の目的語を示す。", "が": "主格の「が」では「決めた」の目的語にならない。", "に": "着点を示し、「決める」の目的語にならない。", "で": "手段・場所を示し、ここでは非文になる。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "使っていたものをやめること。新しく取り入れる導入の反対。"}, {"text": "採用", "is_correct": false, "explanation": "取り入れる意味で、導入に近い。対義ではない。"}, {"text": "改良", "is_correct": false, "explanation": "よくすること。反対の意味ではない。"}, {"text": "購入", "is_correct": false, "explanation": "買うこと。導入の反対ではない。"}], "correct_answer": "廃止", "explanations": {"廃止": "使っていたものをやめること。新しく取り入れる導入の反対。", "採用": "取り入れる意味で、導入に近い。対義ではない。", "改良": "よくすること。反対の意味ではない。", "購入": "買うこと。導入の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35296, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "導入", "is_correct": true, "explanation": "正しい音。"}, {"text": "動乱", "is_correct": false, "explanation": "「どうらん」。後半「にゅう」が「らん」になる。"}, {"text": "導線", "is_correct": false, "explanation": "「どうせん」。後半「にゅう」が「せん」になる。"}, {"text": "道中", "is_correct": false, "explanation": "「どうちゅう」。三拍目「にゅ」が「ちゅ」になる一モーラ差。"}], "explanations": {"導入": "正しい音。", "動乱": "「どうらん」。後半「にゅう」が「らん」になる。", "導線": "「どうせん」。後半「にゅう」が「せん」になる。", "道中": "「どうちゅう」。三拍目「にゅ」が「ちゅ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "導入"}, "level_3": {"options": [{"text": "導入", "is_correct": true, "explanation": "意味：カード払いを店に新しく取り入れるので合う。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：店がカード払いを卒業するのは文脈に合わない。"}, {"text": "運動", "is_correct": false, "explanation": "項構造：「カード払いを運動する」は言えない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：カード払いは料理するものではない。"}], "explanations": {"導入": "意味：カード払いを店に新しく取り入れるので合う。", "卒業": "意味：店がカード払いを卒業するのは文脈に合わない。", "運動": "項構造：「カード払いを運動する」は言えない。", "料理": "意味：カード払いは料理するものではない。"}, "sentence_index": 6, "correct_answer": "導入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場がロボットを導入したので、働く人は増えた。", "explanation": "意味の誤り：ロボットの導入で人が増えるのは文の流れに合わない。"}, {"text": "工場はロボットで導入した。", "explanation": "助詞の誤り：取り入れるものは「を」で示す。"}, {"text": "ロボットを導入しているので、昨日働く人を減らす。", "explanation": "アスペクトの誤り：「昨日」と「減らす」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35296, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は来月からカード払いが導入する。", "corrected_sentence": "店は来月からカード払いを導入する。", "error_description": "助詞の誤り：他動詞「導入する」の目的語は「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35296, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「賛成」の対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「賛成です」は「を」で対象をとらない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示し、ここでは非文。"}, {"text": "が", "is_correct": false, "explanation": "主格になり「導入が賛成です」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「賛成」の対象を示す。", "を": "「賛成です」は「を」で対象をとらない。", "で": "場所・手段を示し、ここでは非文。", "が": "主格になり「導入が賛成です」は意味が通らない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "が": "topic_vs_subject"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "廃止", "is_correct": true, "explanation": "制度などをやめること。導入の対義語。"}, {"text": "開始", "is_correct": false, "explanation": "始めること。導入と近く、対義ではない。"}, {"text": "利用", "is_correct": false, "explanation": "使うこと。反対の意味ではない。"}, {"text": "整備", "is_correct": false, "explanation": "整えること。対義ではない。"}], "correct_answer": "廃止", "explanations": {"廃止": "制度などをやめること。導入の対義語。", "開始": "始めること。導入と近く、対義ではない。", "利用": "使うこと。反対の意味ではない。", "整備": "整えること。対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同一", "is_correct": true, "explanation": "聞こえた音「どういつ」。"}, {"text": "統一", "is_correct": false, "explanation": "「とういつ」。「ど」と「と」の清濁の違い。"}, {"text": "動員", "is_correct": false, "explanation": "「どういん」。最後の「つ」が「ん」になる一モーラ差。"}, {"text": "同質", "is_correct": false, "explanation": "「どうしつ」。三拍目「い」が「し」になる一モーラ差。"}], "explanations": {"同一": "聞こえた音「どういつ」。", "統一": "「とういつ」。「ど」と「と」の清濁の違い。", "動員": "「どういん」。最後の「つ」が「ん」になる一モーラ差。", "同質": "「どうしつ」。三拍目「い」が「し」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "同一"}, "level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "意味：二人が同じ学校に通うことを表す。"}, {"text": "有名", "is_correct": false, "explanation": "意味：文としては言えるが「同じ」の意味にならず文脈に合わない。"}, {"text": "静か", "is_correct": false, "explanation": "連語：「静かの学校」は言えない。"}, {"text": "元気", "is_correct": false, "explanation": "連語：「元気の学校」は不自然。"}], "explanations": {"同一": "意味：二人が同じ学校に通うことを表す。", "有名": "意味：文としては言えるが「同じ」の意味にならず文脈に合わない。", "静か": "連語：「静かの学校」は言えない。", "元気": "連語：「元気の学校」は不自然。"}, "sentence_index": 0, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同一な問題が二回出た。", "explanation": "活用の誤り：同一は名詞の前で「の」をとる。"}, {"text": "同一の問題を二回出た。", "explanation": "助詞の誤り：自動詞「出た」の主語は「が」。"}, {"text": "二つの答えは同一だが、違う。", "explanation": "意味の誤り：同じだと言って違うと続けるのは矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この二つの文は同一くない。", "corrected_sentence": "この二つの文は同一ではない。", "error_description": "活用の誤り：同一は形容詞ではないので否定は「同一ではない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同一", "is_correct": true, "explanation": "「だ」の前は語幹そのまま。"}, {"text": "同一に", "is_correct": false, "explanation": "「にだ」は続かない。連用形で文が終われない。"}, {"text": "同一の", "is_correct": false, "explanation": "連体の「の」は後に名詞が必要。"}, {"text": "同一で", "is_correct": false, "explanation": "「でだ」は続かない。"}], "correct_form": "同一", "base_form": "同一", "form_label": "語幹（だの前）", "sentence_index": 1, "explanations": {"同一": "「だ」の前は語幹そのまま。", "同一に": "「にだ」は続かない。連用形で文が終われない。", "同一の": "連体の「の」は後に名詞が必要。", "同一で": "「でだ」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別", "is_correct": true, "explanation": "同じではないこと。同一の対義。"}, {"text": "同様", "is_correct": false, "explanation": "同じようであること。対義ではない。"}, {"text": "正確", "is_correct": false, "explanation": "間違いがないこと。反対の意味ではない。"}, {"text": "確か", "is_correct": false, "explanation": "まちがいないこと。対義ではない。"}], "correct_answer": "別", "explanations": {"別": "同じではないこと。同一の対義。", "同様": "同じようであること。対義ではない。", "正確": "間違いがないこと。反対の意味ではない。", "確か": "まちがいないこと。対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同一", "is_correct": true, "explanation": "正しい音。"}, {"text": "統治", "is_correct": false, "explanation": "「とうち」。清濁と「い」の脱落が違う。"}, {"text": "同意", "is_correct": false, "explanation": "「どうい」。最後の「つ」がない。"}, {"text": "堂々", "is_correct": false, "explanation": "「どうどう」。後半「いつ」が「どう」になる。"}], "explanations": {"同一": "正しい音。", "統治": "「とうち」。清濁と「い」の脱落が違う。", "同意": "「どうい」。最後の「つ」がない。", "堂々": "「どうどう」。後半「いつ」が「どう」になる。"}, "sentence_index": null, "correct_answer": "同一"}, "level_3": {"options": [{"text": "同一", "is_correct": true, "explanation": "意味：答えが全く同じなので写したと思われた。"}, {"text": "簡単", "is_correct": false, "explanation": "意味：答えが簡単でも写したとは思われない。"}, {"text": "丁寧", "is_correct": false, "explanation": "意味：丁寧な答えは写した理由にならない。"}, {"text": "無理", "is_correct": false, "explanation": "意味：文の流れに合わない。"}], "explanations": {"同一": "意味：答えが全く同じなので写したと思われた。", "簡単": "意味：答えが簡単でも写したとは思われない。", "丁寧": "意味：丁寧な答えは写した理由にならない。", "無理": "意味：文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "同一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼と私の意見は同一だったので、けんかした。", "explanation": "意味の誤り：同じ意見ならけんかの理由にならない。"}, {"text": "彼と私の意見を同一だった。", "explanation": "助詞の誤り：主題は「は」で示す。"}, {"text": "一匹の同一の意見がある。", "explanation": "助数詞の誤り：意見は「匹」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "答えが同一だので、写したと思われた。", "corrected_sentence": "答えが同一なので、写したと思われた。", "error_description": "活用の誤り：「ので」の前では「同一な」になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同一", "is_correct": true, "explanation": "名詞の前では語幹に「の」が続く。"}, {"text": "同一だ", "is_correct": false, "explanation": "「同一だの場所」とは言えない。"}, {"text": "同一に", "is_correct": false, "explanation": "「同一にの」は続かない。"}, {"text": "同一で", "is_correct": false, "explanation": "「同一での場所」は不自然。"}], "correct_form": "同一", "base_form": "同一", "form_label": "語幹（のの前）", "sentence_index": 7, "explanations": {"同一": "名詞の前では語幹に「の」が続く。", "同一だ": "「同一だの場所」とは言えない。", "同一に": "「同一にの」は続かない。", "同一で": "「同一での場所」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35298, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "別々", "is_correct": true, "explanation": "それぞれ違うこと。同一の反対。"}, {"text": "同等", "is_correct": false, "explanation": "同じ程度であること。対義ではない。"}, {"text": "平等", "is_correct": false, "explanation": "差がないこと。対義ではない。"}, {"text": "確実", "is_correct": false, "explanation": "まちがいないこと。対義ではない。"}], "correct_answer": "別々", "explanations": {"別々": "それぞれ違うこと。同一の反対。", "同等": "同じ程度であること。対義ではない。", "平等": "差がないこと。対義ではない。", "確実": "まちがいないこと。対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35302, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期間", "is_correct": true, "explanation": "聞こえた音「きかん」。"}, {"text": "機械", "is_correct": false, "explanation": "「きかい」。最後の「ん」が「い」になる一モーラ差。"}, {"text": "危険", "is_correct": false, "explanation": "「きけん」。二拍目の「か」が「け」になる一モーラ差。"}, {"text": "時間", "is_correct": false, "explanation": "「じかん」。一拍目の「き」が「じ」になる一モーラ差。"}], "explanations": {"期間": "聞こえた音「きかん」。", "機械": "「きかい」。最後の「ん」が「い」になる一モーラ差。", "危険": "「きけん」。二拍目の「か」が「け」になる一モーラ差。", "時間": "「じかん」。一拍目の「き」が「じ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "期間"}, "level_3": {"options": [{"text": "期間", "is_correct": true, "explanation": "意味：テストが続いている間を表す。"}, {"text": "場所", "is_correct": false, "explanation": "意味：「テストの場所は部活が休み」では意味が通らない。"}, {"text": "点数", "is_correct": false, "explanation": "意味：点数と部活の休みは結びつかない。"}, {"text": "答え", "is_correct": false, "explanation": "意味：文脈に合わない。"}], "explanations": {"期間": "意味：テストが続いている間を表す。", "場所": "意味：「テストの場所は部活が休み」では意味が通らない。", "点数": "意味：点数と部活の休みは結びつかない。", "答え": "意味：文脈に合わない。"}, "sentence_index": 0, "correct_answer": "期間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事の期間を、道が通れなくなる。", "explanation": "助詞の誤り：「を」では文がつながらない。"}, {"text": "一枚の期間、道が通れなくなる。", "explanation": "助数詞の誤り：期間は「枚」で数えない。"}, {"text": "工事の期間、道が通れなくなった明日。", "explanation": "語順の誤り：「明日」の位置と時制が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35302, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この期間をプールが使えない。", "corrected_sentence": "この期間はプールが使えない。", "error_description": "助詞の誤り：時を表す「この期間」に「を」はつかない。主題の「は」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
