INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35303, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「覚えた」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、ここでは非文。"}, {"text": "が", "is_correct": false, "explanation": "主格では他動詞「覚えた」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "着点を示し、「日本語に覚えた」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「覚えた」の目的語を示す。", "へ": "方向を示し、ここでは非文。", "が": "主格では他動詞「覚えた」の目的語にならない。", "に": "着点を示し、「日本語に覚えた」は不自然。"}, "error_tags": {"へ": "direction", "が": "object_marking", "に": "location_vs_target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35304, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数百", "is_correct": true, "explanation": "聞こえた音「すうひゃく」。"}, {"text": "九百", "is_correct": false, "explanation": "「きゅうひゃく」。一拍目の「す」が「きゅ」になる一モーラ差。"}, {"text": "数泊", "is_correct": false, "explanation": "「すうはく」。三拍目の「ひゃ」が「は」になる一モーラ差。"}, {"text": "数尺", "is_correct": false, "explanation": "「すうしゃく」。三拍目の「ひゃ」が「しゃ」になる一モーラ差。"}], "explanations": {"数百": "聞こえた音「すうひゃく」。", "九百": "「きゅうひゃく」。一拍目の「す」が「きゅ」になる一モーラ差。", "数泊": "「すうはく」。三拍目の「ひゃ」が「は」になる一モーラ差。", "数尺": "「すうしゃく」。三拍目の「ひゃ」が「しゃ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "数百"}, "level_3": {"options": [{"text": "数百", "is_correct": true, "explanation": "意味：百がいくつか集まった人数を表す。"}, {"text": "少し", "is_correct": false, "explanation": "連語：「少し人」とは言えない。"}, {"text": "全部", "is_correct": false, "explanation": "連語：「全部人」とは言えない。"}, {"text": "大勢", "is_correct": false, "explanation": "連語：「大勢人」とは言わない。"}], "explanations": {"数百": "意味：百がいくつか集まった人数を表す。", "少し": "連語：「少し人」とは言えない。", "全部": "連語：「全部人」とは言えない。", "大勢": "連語：「大勢人」とは言わない。"}, "sentence_index": 0, "correct_answer": "数百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数百年前の家がまだ残った明日。", "explanation": "時制・語順の誤り：「明日」と過去形が合わない。"}, {"text": "数百冊前の家がまだ残っている。", "explanation": "助数詞の誤り：時は「冊」で数えない。"}, {"text": "数百年前の家をまだ残っている。", "explanation": "助詞の誤り：自動詞「残る」の主語は「が」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35304, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会場には数百冊の人が集まった。", "corrected_sentence": "会場には数百人が集まった。", "error_description": "助数詞の誤り：人は「冊」ではなく「人」で数える。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35304, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "値段（手段）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「数百円を買える」は目的語が値段になり非文。"}, {"text": "に", "is_correct": false, "explanation": "「数百円に買える」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、ここでは非文。"}], "correct_answer": "で", "explanations": {"で": "値段（手段）を示す。", "を": "「数百円を買える」は目的語が値段になり非文。", "に": "「数百円に買える」は不自然。", "へ": "方向を示し、ここでは非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35304, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "数百", "is_correct": true, "explanation": "正しい音。"}, {"text": "数学", "is_correct": false, "explanation": "「すうがく」。後半「ひゃく」が「がく」になる。"}, {"text": "百", "is_correct": false, "explanation": "「ひゃく」。最初の「すう」がない。"}, {"text": "数発", "is_correct": false, "explanation": "「すうはつ」。後半が「はつ」になる。"}], "explanations": {"数百": "正しい音。", "数学": "「すうがく」。後半「ひゃく」が「がく」になる。", "百": "「ひゃく」。最初の「すう」がない。", "数発": "「すうはつ」。後半が「はつ」になる。"}, "sentence_index": null, "correct_answer": "数百"}, "level_3": {"options": [{"text": "数百", "is_correct": true, "explanation": "意味：百がいくつか集まった数の鳥。"}, {"text": "全部", "is_correct": false, "explanation": "連語：「全部羽」とは言えない。"}, {"text": "たくさん", "is_correct": false, "explanation": "連語：「たくさん羽」とは言えない。"}, {"text": "少し", "is_correct": false, "explanation": "連語：「少し羽」とは言えない。"}], "explanations": {"数百": "意味：百がいくつか集まった数の鳥。", "全部": "連語：「全部羽」とは言えない。", "たくさん": "連語：「たくさん羽」とは言えない。", "少し": "連語：「少し羽」とは言えない。"}, "sentence_index": 6, "correct_answer": "数百"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祭りには数百匹の車が来た。", "explanation": "助数詞の誤り：車は「台」で数える。"}, {"text": "祭りを数百台の車が来た。", "explanation": "助詞の誤り：場所は「に」で示す。"}, {"text": "祭りには数百台の車が来る昨日。", "explanation": "時制の誤り：「昨日」と現在形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
