INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35304, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "も", "options": [{"text": "も", "is_correct": true, "explanation": "数が多いことを強める。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、ここでは非文。"}, {"text": "が", "is_correct": false, "explanation": "「数百年が生きている」は主語にならず非文。"}, {"text": "と", "is_correct": false, "explanation": "相手を示し、意味が通らない。"}], "correct_answer": "も", "explanations": {"も": "数が多いことを強める。", "へ": "方向を示し、ここでは非文。", "が": "「数百年が生きている」は主語にならず非文。", "と": "相手を示し、意味が通らない。"}, "error_tags": {"へ": "direction", "が": "topic_vs_subject", "と": "other"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35305, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数百", "is_correct": true, "explanation": "聞こえた音「すうひゃく」。"}, {"text": "数尺", "is_correct": false, "explanation": "「すうしゃく」。三拍目の「ひゃ」が「しゃ」になる一モーラ差。"}, {"text": "九百", "is_correct": false, "explanation": "「きゅうひゃく」。一拍目の「す」が「きゅ」になる一モーラ差。"}, {"text": "数泊", "is_correct": false, "explanation": "「すうはく」。三拍目の「ひゃ」が「は」になる一モーラ差。"}], "explanations": {"数百": "聞こえた音「すうひゃく」。", "数尺": "「すうしゃく」。三拍目の「ひゃ」が「しゃ」になる一モーラ差。", "九百": "「きゅうひゃく」。一拍目の「す」が「きゅ」になる一モーラ差。", "数泊": "「すうはく」。三拍目の「ひゃ」が「は」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "数百"}, "level_3": {"options": [{"text": "数百", "is_correct": true, "explanation": "意味：正確でないが百の数倍ほどの人数。"}, {"text": "何", "is_correct": false, "explanation": "文法：「何人はいた」とは言えない（「何人か」が必要）。"}, {"text": "毎", "is_correct": false, "explanation": "連語：「毎人」とは言わない。"}, {"text": "全", "is_correct": false, "explanation": "連語：「全人」とは言わない。"}], "explanations": {"数百": "意味：正確でないが百の数倍ほどの人数。", "何": "文法：「何人はいた」とは言えない（「何人か」が必要）。", "毎": "連語：「毎人」とは言わない。", "全": "連語：「全人」とは言わない。"}, "sentence_index": 0, "correct_answer": "数百"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数百ものコメントを届いた。", "explanation": "助詞の誤り：自動詞「届く」の主語は「が」。"}, {"text": "数百本ものコメントが届いた。", "explanation": "助数詞の誤り：コメントは「本」で数えない。"}, {"text": "数百ものコメントが届く昨日。", "explanation": "時制の誤り：「昨日」と現在形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5c6c66e-fc4f-480d-8fab-8c782e9c9160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
