INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35308, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "千がいくつか集まった数。", "primary_collocate": null, "pronunciation": "すうせん", "ipa": "sɯːseɴ", "syllable_count": 4, "sentences": [{"text": "数千人がこの町に住んでいる。", "target_word": "数千", "complexity_tier": "T3", "furigana": "すうせんにん まち す", "sentence_source": "generated"}, {"text": "会場には数千の人が来た。", "target_word": "数千", "complexity_tier": "T3", "furigana": "かいじょう すうせん ひと き", "sentence_source": "generated"}, {"text": "この本は数千円します。", "target_word": "数千", "complexity_tier": "T3", "furigana": "ほん すうせんえん", "sentence_source": "generated"}, {"text": "空に数千の星が見えた。", "target_word": "数千", "complexity_tier": "T3", "furigana": "そら すうせん ほし み", "sentence_source": "generated"}, {"text": "数千もの手紙が届きました。", "target_word": "数千", "complexity_tier": "T3", "furigana": "すうせん てがみ とど", "sentence_source": "generated"}, {"text": "その鳥は数千キロも飛ぶ。", "target_word": "数千", "complexity_tier": "T3", "furigana": "すうせん と", "sentence_source": "generated"}, {"text": "数千年前の道具が見つかった。", "target_word": "数千", "complexity_tier": "T3", "furigana": "すうせんねんまえ どうぐ み", "sentence_source": "generated"}, {"text": "被害は数千に上るそうだ。", "target_word": "数千", "complexity_tier": "T3", "furigana": "ひがい すうせん のぼ", "sentence_source": "generated"}, {"text": "毎日数千人が駅を使う。", "target_word": "数千", "complexity_tier": "T3", "furigana": "まいにち すうせんにん えき つか", "sentence_source": "generated"}, {"text": "数千本の木が植えられている。", "target_word": "数千", "complexity_tier": "T3", "furigana": "すうせんぼん き う", "sentence_source": "generated"}], "morphological_forms": [{"form": "数千人", "label": "派生"}, {"form": "数千年", "label": "派生"}, {"form": "数千円", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 千が数個集まった数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-co