INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35306, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "正解：「部」（ぶ）。"}, {"text": "府", "is_correct": false, "explanation": "「府」（ふ）は「ぶ」と清濁だけが違う一モーラ差。"}, {"text": "具", "is_correct": false, "explanation": "「具」（ぐ）は子音が「b」から「g」に変わる一モーラ差。"}, {"text": "美", "is_correct": false, "explanation": "「美」（び）は母音が「う」から「い」に変わる一モーラ差。"}, {"text": "場", "is_correct": false, "explanation": "「場」（ば）は母音が「う」から「あ」に変わる一モーラ差。"}, {"text": "区", "is_correct": false, "explanation": "「区」（く）は子音と清濁が違う一モーラ差。"}], "explanations": {"部": "正解：「部」（ぶ）。", "府": "「府」（ふ）は「ぶ」と清濁だけが違う一モーラ差。", "具": "「具」（ぐ）は子音が「b」から「g」に変わる一モーラ差。", "美": "「美」（び）は母音が「う」から「い」に変わる一モーラ差。", "場": "「場」（ば）は母音が「う」から「あ」に変わる一モーラ差。", "区": "「区」（く）は子音と清濁が違う一モーラ差。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "匹", "is_correct": false, "explanation": "意味：「匹」は動物を数えることばで、本には使わない。"}, {"text": "台", "is_correct": false, "explanation": "意味：「台」は機械や車を数えることばで、本には使わない。"}, {"text": "杯", "is_correct": false, "explanation": "連語：「杯」は飲み物を数えることばで、本には合わない。"}], "explanations": {"部": "正解：文脈に合う。", "匹": "意味：「匹」は動物を数えることばで、本には使わない。", "台": "意味：「台」は機械や車を数えることばで、本には使わない。", "杯": "連語：「杯」は飲み物を数えることばで、本には合わない。"}, "sentence_index": 0, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬を三部飼っています。", "explanation": "助数詞の誤り：犬は「匹」で数える。"}, {"text": "ジュースを一部飲みました。", "explanation": "助数詞の誤り：飲み物は「杯」で数える。"}, {"text": "鉛筆を二部買いました。", "explanation": "助数詞の誤り：鉛筆は「本」で数える。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4efa1da3-a167-4fbd-a948-15045133712c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EX