INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35308, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数千", "is_correct": true, "explanation": "正解：「数千」（すうせん）。"}, {"text": "推薦", "is_correct": false, "explanation": "「推薦」（すいせん）は「う」が「い」に変わる一モーラ差。"}, {"text": "数年", "is_correct": false, "explanation": "「数年」（すうねん）は「せ」が「ね」に変わる一モーラ差。"}, {"text": "数万", "is_correct": false, "explanation": "「数万」（すうまん）は「せ」が「ま」に変わる一モーラ差。"}, {"text": "数件", "is_correct": false, "explanation": "「数件」（すうけん）は「せ」が「け」に変わる一モーラ差。"}], "explanations": {"数千": "正解：「数千」（すうせん）。", "推薦": "「推薦」（すいせん）は「う」が「い」に変わる一モーラ差。", "数年": "「数年」（すうねん）は「せ」が「ね」に変わる一モーラ差。", "数万": "「数万」（すうまん）は「せ」が「ま」に変わる一モーラ差。", "数件": "「数件」（すうけん）は「せ」が「け」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "数千"}, "level_3": {"options": [{"text": "数千", "is_correct": true, "explanation": "正解：文脈に合う。"}, {"text": "数字", "is_correct": false, "explanation": "意味：「数字人」とは言わず、人の数を表さない。"}, {"text": "数学", "is_correct": false, "explanation": "意味：教科の名前で、人の数を表さない。"}, {"text": "番号", "is_correct": false, "explanation": "連語：「番号人」という言い方はない。"}], "explanations": {"数千": "正解：文脈に合う。", "数字": "意味：「数字人」とは言わず、人の数を表さない。", "数学": "意味：教科の名前で、人の数を表さない。", "番号": "連語：「番号人」という言い方はない。"}, "sentence_index": 0, "correct_answer": "数千"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数千の水が流れた。", "explanation": "数えられない「水」に「数千」は直接使えない。"}, {"text": "数千冊の鳥が飛んでいる。", "explanation": "助数詞の誤り：鳥は「羽」で数える。"}, {"text": "ちょうど数千人が来た。", "explanation": "「数千」ははっきりしない数で、「ちょうど」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4efa1da3-a167-4fbd-a948-15045133712c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validat