INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35316, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体のすぐ近くのところ。", "primary_collocate": null, "pronunciation": "てもと", "ipa": "temoto", "syllable_count": 3, "sentences": [{"text": "手元を明るくして本を読む。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元が暗くて字が見えない。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "彼は手元を見ずに文字を打つ。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "料理中は手元に注意してね。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元のライトをつけてください。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元が影になって見えにくい。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "暗いので手元を照らした。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "職人の手元に光が当たる。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元をよく見て切りなさい。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元の明かりが消えてしまった。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}], "morphological_forms": [{"form": "お手元", "label": "敬語形"}, {"form": "手元灯", "label": "派生"}, {"form": "手元資料", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の体のすぐ近くの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '521221c4-6986-4d3b-8cf9-c0ad90100f