INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35317, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の手が届くあたり。すぐ使えるところ。", "primary_collocate": null, "pronunciation": "てもと", "ipa": "temoto", "syllable_count": 3, "sentences": [{"text": "辞書をいつも手元に置いている。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "今、手元にお金がない。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元の資料を見てください。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "その本は今手元にありません。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "スマホを手元に置いて寝る。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元にあるペンを貸して。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元の地図で道を調べた。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "大事な写真は手元に残したい。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元に水を用意しておこう。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}, {"text": "手元の紙にメモを書いた。", "target_word": "手元", "complexity_tier": "T3", "furigana": "てもと", "sentence_source": "generated"}], "morphological_forms": [{"form": "お手元", "label": "敬語形"}, {"form": "手元資料", "label": "派生"}, {"form": "手元金", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の手の届くすぐ近くの所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '521221c4-6986-4d3b-8cf9-c0ad9