INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35318, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "文字を読んだり書いたりできること。", "primary_collocate": null, "pronunciation": "しきじ", "ipa": "ɕikʲidʑi", "syllable_count": 3, "sentences": [{"text": "この国では識字が広まった。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の教室に通う大人もいる。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字は生活に大切だ。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "昔は識字の機会がない人も多かった。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字を助ける本を作った。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "祖母は六十歳で識字の勉強を始めた。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の問題について話し合う。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字が進むと仕事も増える。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "村で識字の運動が始まった。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の大切さを感じている。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "識字率", "label": "派生"}, {"form": "識字教育", "label": "派生"}, {"form": "非識字", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 文字を読み書きできる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '521221c4-6986-4d3b-8cf9-