INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35319, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "文字の読み書きができる能力。", "primary_collocate": null, "pronunciation": "しきじ", "ipa": "ɕikʲidʑi", "syllable_count": 3, "sentences": [{"text": "識字の力を身につけたい。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "彼女は識字の力が高い。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の能力をテストで調べる。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字は学ぶことで伸びる。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "子どもの識字を育てる。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の力がないと困る。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字が弱い人を手伝う。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "読書で識字の力がついた。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "識字の力は一生の宝だ。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}, {"text": "先生は識字を大切にしている。", "target_word": "識字", "complexity_tier": "T3", "furigana": "しきじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "識字率", "label": "派生"}, {"form": "識字能力", "label": "派生"}, {"form": "識字教育", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 文字を読み書きする能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '521221c4-6986-4d3b-8cf9-c0ad90100fa2') ON CO