INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35320, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体の中でどのくらいかという割合。", "primary_collocate": null, "pronunciation": "りつ", "ipa": "ɾitsɯ", "syllable_count": 2, "sentences": [{"text": "今年は去年より率が上がった。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "このチームは勝つ率が高い。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "率で見るとよくわかる。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "この病気が治る率は高い。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "失敗の率を下げたい。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "その率は半分ぐらいだ。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "出席する人の率を調べた。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "高い率で成功している。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "率が変わった理由を考える。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}, {"text": "男女の率はほぼ同じだ。", "target_word": "率", "complexity_tier": "T3", "furigana": "りつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "比率", "label": "派生"}, {"form": "確率", "label": "派生"}, {"form": "合格率", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 全体に対する割合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '521221c4-6986-4d3b-8cf9-c0ad90100fa2') ON CONFLICT (sense_id, asset_type)