INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35310, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可能", "is_correct": true, "explanation": "正解。「可能」（かのう）。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日」（きのう）。一拍目「か」が「き」。"}, {"text": "加工", "is_correct": false, "explanation": "「加工」（かこう）。二拍目「の」が「こ」。"}, {"text": "過労", "is_correct": false, "explanation": "「過労」（かろう）。二拍目「の」が「ろ」。"}, {"text": "仮装", "is_correct": false, "explanation": "「仮装」（かそう）。二拍目「の」が「そ」。"}], "explanations": {"可能": "正解。「可能」（かのう）。", "昨日": "「昨日」（きのう）。一拍目「か」が「き」。", "加工": "「加工」（かこう）。二拍目「の」が「こ」。", "過労": "「過労」（かろう）。二拍目「の」が「ろ」。", "仮装": "「仮装」（かそう）。二拍目「の」が「そ」。"}, "sentence_index": null, "correct_answer": "可能"}, "level_3": {"options": [{"text": "可能", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "静か", "is_correct": false, "explanation": "意味：音がないようすで、終わらせることには合わない。"}, {"text": "親切", "is_correct": false, "explanation": "意味：人へのやさしさで、事がらには合わない。"}, {"text": "有名", "is_correct": false, "explanation": "意味：よく知られていることで、文意に合わない。"}], "explanations": {"可能": "正解。文の意味に合う。", "静か": "意味：音がないようすで、終わらせることには合わない。", "親切": "意味：人へのやさしさで、事がらには合わない。", "有名": "意味：よく知られていることで、文意に合わない。"}, "sentence_index": 0, "correct_answer": "可能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "可能の本を三冊買った。", "explanation": "助詞の誤り：形状詞は「の」でなく「な」で名詞につく。"}, {"text": "明日は雨が可能です。", "explanation": "意味の誤り：自然現象の「かもしれない」には使わない。"}, {"text": "彼は可能して走った。", "explanation": "活用の誤り：「可能する」という形はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9efaa47d-b462-4036-bc76-0e1fdf59a13b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
