INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "前に向かって動くこと。", "primary_collocate": null, "pronunciation": "すすむ", "ipa": "sɯsɯmɯ", "syllable_count": 3, "sentences": [{"text": "車がゆっくり前に進む。", "target_word": "進む", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "私たちは道をまっすぐ進んだ。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "列が少しずつ進んでいる。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "雪で前に進めなかった。", "target_word": "進め", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "船が北へ進んでいく。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "人が多くて進まない。", "target_word": "進ま", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "右に曲がらずに進んでください。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "前に進む人の後ろを歩いた。", "target_word": "進む", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "暗い森の中を進んだ。", "target_word": "進ん", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}, {"text": "ボートが川を進む様子を見た。", "target_word": "進む", "complexity_tier": "T3", "furigana": "すす", "sentence_source": "generated"}], "morphological_forms": [{"form": "進んだ", "label": "活用"}, {"form": "進んで", "label": "活用"}, {"form": "進まない", "label": "活用"}, {"form": "進める", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 前の方へ向かって動いていく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669e35ba-3da9-4a99-8341-3739