INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35330, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ほかのものとはっきりちがって、とりわけ、ということを表す言葉。", "primary_collocate": null, "pronunciation": "とくに", "ipa": "tokɯɲi", "syllable_count": 3, "sentences": [{"text": "果物の中で特にりんごが好きだ。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "今日は特に寒いですね。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "特に問題はありません。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "数学が特に難しかった。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "夏は特に水をよく飲む。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "彼は特に歌がうまい。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "この店は特にケーキが有名だ。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "特に言うことはないです。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "朝は特に道が混んでいる。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}, {"text": "特に気をつけてほしい点がある。", "target_word": "特に", "complexity_tier": "T3", "furigana": "とく", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 他と比べてとりわけそうだ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669e35ba-3da9-4a99-8341-37399f2f154a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXC