INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35332, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "悪いところを直して、もっとよくすること。", "primary_collocate": null, "pronunciation": "かいかく", "ipa": "kaikakɯ", "syllable_count": 4, "sentences": [{"text": "学校の改革が始まった。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "政府は大きな改革をした。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "改革に反対する人もいる。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "市長は改革を約束した。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "この改革で働き方が変わった。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "改革の結果を見守っている。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "会社の改革は時間がかかる。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "改革を進めるのは大変だ。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "新しい改革の案が出された。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}, {"text": "みんなで改革について話した。", "target_word": "改革", "complexity_tier": "T3", "furigana": "かいかく", "sentence_source": "generated"}], "morphological_forms": [{"form": "改革する", "label": "派生"}, {"form": "改革案", "label": "派生"}, {"form": "改革者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 制度などを直してよくすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669e35ba-3da9-4a99-8