INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35324, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「AとB」で二つのものを並べる。"}, {"text": "を", "is_correct": false, "explanation": "「運動を食事」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「運動で食事の」はつながらない。"}, {"text": "が", "is_correct": false, "explanation": "「運動が食事の」は非文になる。"}], "correct_answer": "と", "explanations": {"と": "「AとB」で二つのものを並べる。", "を": "「運動を食事」は意味が通らない。", "で": "「運動で食事の」はつながらない。", "が": "「運動が食事の」は非文になる。"}, "error_tags": {"を": "object_marking", "で": "instrument", "が": "topic_vs_subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相殺", "is_correct": true, "explanation": "力が打ち消し合って効果がなくなる「相殺」は相乗の対義。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、相乗に近く対義ではない。"}, {"text": "増加", "is_correct": false, "explanation": "増えることで、対義ではない。"}, {"text": "結合", "is_correct": false, "explanation": "結びつくことで、対義ではない。"}], "correct_answer": "相殺", "explanations": {"相殺": "力が打ち消し合って効果がなくなる「相殺」は相乗の対義。", "協力": "力を合わせることで、相乗に近く対義ではない。", "増加": "増えることで、対義ではない。", "結合": "結びつくことで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35324, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "相乗", "is_correct": true, "explanation": "正しい語です。"}, {"text": "登場", "is_correct": false, "explanation": "「登場」はとうじょう。最初の「そ」が「と」に変わる一モーラ差。"}, {"text": "双方", "is_correct": false, "explanation": "「双方」はそうほう。「じょ」が「ほ」に変わる一モーラ差。"}, {"text": "相当", "is_correct": false, "explanation": "「相当」はそうとう。「じょ」が「と」に変わる一モーラ差。"}, {"text": "早急", "is_correct": false, "explanation": "「早急」はそうきゅう。「じょ」が「きゅ」に変わる一モーラ差。"}, {"text": "送料", "is_correct": false, "explanation": "「送料」はそうりょう。「じょ」が「りょ」に変わる一モーラ差。"}], "explanations": {"相乗": "正しい語です。", "登場": "「登場」はとうじょう。最初の「そ」が「と」に変わる一モーラ差。", "双方": "「双方」はそうほう。「じょ」が「ほ」に変わる一モーラ差。", "相当": "「相当」はそうとう。「じょ」が「と」に変わる一モーラ差。", "早急": "「早急」はそうきゅう。「じょ」が「きゅ」に変わる一モーラ差。", "送料": "「送料」はそうりょう。「じょ」が「りょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "相乗"}, "level_3": {"options": [{"text": "相乗", "is_correct": true, "explanation": "組み合わせで効果が大きくなる「相乗効果」が高い、で自然。"}, {"text": "逆", "is_correct": false, "explanation": "意味：「逆効果が高い」は組み合わせをほめる文意に合わない。"}, {"text": "副", "is_correct": false, "explanation": "意味：「副効果」は主な効果ではなく、文意とずれる。"}, {"text": "即", "is_correct": false, "explanation": "連語：「即効果」とは言わず「即効」と言う。"}], "explanations": {"相乗": "組み合わせで効果が大きくなる「相乗効果」が高い、で自然。", "逆": "意味：「逆効果が高い」は組み合わせをほめる文意に合わない。", "副": "意味：「副効果」は主な効果ではなく、文意とずれる。", "即": "連語：「即効果」とは言わず「即効」と言う。"}, "sentence_index": 6, "correct_answer": "相乗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相乗効果で成果を上がった。", "explanation": "助詞の混同：自動詞「上がる」に「を」は使えない。"}, {"text": "相乗効果で成果が上がっているた。", "explanation": "活用の誤り：「ている」と「た」が混ざって非文。"}, {"text": "相乗効果で成果が二枚上がった。", "explanation": "助数詞の誤り：成果を「枚」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
