INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正しい語です。"}, {"text": "涼む", "is_correct": false, "explanation": "「涼む」はすずむ。二つ目の「す」が「ず」になる清濁の違い。"}, {"text": "濯ぐ", "is_correct": false, "explanation": "「濯ぐ」はすすぐ。最後の「む」が「ぐ」に変わる一モーラ差。"}, {"text": "荒む", "is_correct": false, "explanation": "「荒む」はすさむ。二つ目の「す」が「さ」に変わる一モーラ差。"}, {"text": "竦む", "is_correct": false, "explanation": "「竦む」はすくむ。二つ目の「す」が「く」に変わる一モーラ差。"}], "explanations": {"進む": "正しい語です。", "涼む": "「涼む」はすずむ。二つ目の「す」が「ず」になる清濁の違い。", "濯ぐ": "「濯ぐ」はすすぐ。最後の「む」が「ぐ」に変わる一モーラ差。", "荒む": "「荒む」はすさむ。二つ目の「す」が「さ」に変わる一モーラ差。", "竦む": "「竦む」はすくむ。二つ目の「す」が「く」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進む", "is_correct": true, "explanation": "車が前へ動いていく様子に合う。"}, {"text": "座る", "is_correct": false, "explanation": "項構造：車は「座る」主体にならない。"}, {"text": "眠る", "is_correct": false, "explanation": "意味：車が眠ることはなく「前に」とも合わない。"}, {"text": "笑う", "is_correct": false, "explanation": "意味：車は笑わない。"}], "explanations": {"進む": "車が前へ動いていく様子に合う。", "座る": "項構造：車は「座る」主体にならない。", "眠る": "意味：車が眠ることはなく「前に」とも合わない。", "笑う": "意味：車は笑わない。"}, "sentence_index": 0, "correct_answer": "進む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪を前に進めなかった。", "explanation": "助詞の混同：原因は「で」で表し、「を」は使えない。"}, {"text": "雪で前に進めているなかった。", "explanation": "活用の誤り：「ている」と「なかった」が混ざって非文。"}, {"text": "前に雪で一冊進めなかった。", "explanation": "助数詞の誤り：進む距離を「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.val