INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "通過する場所「道」を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「道が進んだ」だと道が動くことになる。"}, {"text": "で", "is_correct": false, "explanation": "通る道そのものは「で」ではなく「を」で示す。"}, {"text": "から", "is_correct": false, "explanation": "「道から進んだ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "通過する場所「道」を「を」で示す。", "が": "「道が進んだ」だと道が動くことになる。", "で": "通る道そのものは「で」ではなく「を」で示す。", "から": "「道から進んだ」は不自然。"}, "error_tags": {"が": "object_marking", "で": "location_vs_target", "から": "source_vs_goal"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "戻る", "is_correct": true, "explanation": "後ろへ帰る「戻る」は進むの対義。"}, {"text": "走る", "is_correct": false, "explanation": "速く動くことで、対義ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "足で動くことで、対義ではない。"}, {"text": "急ぐ", "is_correct": false, "explanation": "早くしようとすることで、対義ではない。"}], "correct_answer": "戻る", "explanations": {"戻る": "後ろへ帰る「戻る」は進むの対義。", "走る": "速く動くことで、対義ではない。", "歩く": "足で動くことで、対義ではない。", "急ぐ": "早くしようとすることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35328, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "進む", "is_correct": true, "explanation": "正しい語です。"}, {"text": "窄む", "is_correct": false, "explanation": "「窄む」はすぼむ。二つ目の「す」が「ぼ」に変わる一モーラ差。"}, {"text": "包む", "is_correct": false, "explanation": "「包む」はつつむ。「すす」が「つつ」に変わる。"}, {"text": "沈む", "is_correct": false, "explanation": "「沈む」はしずむ。「すす」が「しず」に変わる。"}, {"text": "住む", "is_correct": false, "explanation": "「住む」はすむ。「す」が一つ少ない。"}], "explanations": {"進む": "正しい語です。", "窄む": "「窄む」はすぼむ。二つ目の「す」が「ぼ」に変わる一モーラ差。", "包む": "「包む」はつつむ。「すす」が「つつ」に変わる。", "沈む": "「沈む」はしずむ。「すす」が「しず」に変わる。", "住む": "「住む」はすむ。「す」が一つ少ない。"}, "sentence_index": null, "correct_answer": "進む"}, "level_3": {"options": [{"text": "進ん", "is_correct": true, "explanation": "「〜でください」につながるて形。前へ行く意味。"}, {"text": "座っ", "is_correct": false, "explanation": "意味：曲がらずに座るでは指示として意味が通らない。"}, {"text": "寝", "is_correct": false, "explanation": "意味：曲がらずに寝るは文脈に合わない。"}, {"text": "泣い", "is_correct": false, "explanation": "意味：道の指示として泣くは合わない。"}], "explanations": {"進ん": "「〜でください」につながるて形。前へ行く意味。", "座っ": "意味：曲がらずに座るでは指示として意味が通らない。", "寝": "意味：曲がらずに寝るは文脈に合わない。", "泣い": "意味：道の指示として泣くは合わない。"}, "sentence_index": 6, "correct_answer": "進ん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボートを川が進む様子を見た。", "explanation": "助詞の混同：主語と場所の助詞が入れ替わっている。"}, {"text": "ボートが川を進んでいる様子を見たている。", "explanation": "活用の誤り：「見たている」は非文。"}, {"text": "ボートが一冊川を進む様子を見た。", "explanation": "助数詞の誤り：ボートは「冊」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5665fc7-37dc-46b2-8a22-86e4c6de2204') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_war