INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35346, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのことを一つずつ分けて書いたものの、それぞれの項目。", "primary_collocate": null, "pronunciation": "かじょう", "ipa": "kadʑoː", "syllable_count": 3, "sentences": [{"text": "規則は五つの箇条でできている。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "きそく いつ かじょう", "sentence_source": "generated"}, {"text": "この箇条をよく読んでください。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう よ", "sentence_source": "generated"}, {"text": "約束を三つの箇条にまとめた。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "やくそく みっ かじょう", "sentence_source": "generated"}, {"text": "最初の箇条が一番大切だ。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "さいしょ かじょう いちばん たいせつ", "sentence_source": "generated"}, {"text": "箇条ごとに意見を書いた。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう いけん か", "sentence_source": "generated"}, {"text": "その箇条には反対だ。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう はんたい", "sentence_source": "generated"}, {"text": "新しい箇条が一つ加わった。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "あたら かじょう ひと くわ", "sentence_source": "generated"}, {"text": "箇条の数が多すぎる。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう かず おお", "sentence_source": "generated"}, {"text": "クラスのルールを箇条で示した。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう しめ", "sentence_source": "generated"}, {"text": "二番目の箇条を直した。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "にばんめ かじょう なお", "sentence_source": "generated"}], "morphological_forms": [{"form": "箇条書き", "label": "派生"}, {"form": "か条", "label": "派生"}, {"form": "十箇条", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一つずつ分けて書いた項目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'