INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35333, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改革", "is_correct": true, "explanation": "「かいかく」と読む正解の語。"}, {"text": "会館", "is_correct": false, "explanation": "「かいかん」と読み、集まりに使う建物という意味の別の語。"}, {"text": "開会", "is_correct": false, "explanation": "「かいかい」と読み、会を始めることという意味の別の語。"}, {"text": "体格", "is_correct": false, "explanation": "「たいかく」と読み、体の大きさや形という意味の別の語。"}, {"text": "内閣", "is_correct": false, "explanation": "「ないかく」と読み、国の政治を行う大臣の集まりという意味の別の語。"}], "explanations": {"改革": "「かいかく」と読む正解の語。", "会館": "「かいかん」と読み、集まりに使う建物という意味の別の語。", "開会": "「かいかい」と読み、会を始めることという意味の別の語。", "体格": "「たいかく」と読み、体の大きさや形という意味の別の語。", "内閣": "「ないかく」と読み、国の政治を行う大臣の集まりという意味の別の語。"}, "sentence_index": null, "correct_answer": "改革"}, "level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "学校の仕組みを改めることが始まったので「改革」が合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気が「始まった」とは言わない。"}, {"text": "机", "is_correct": false, "explanation": "机が始まることはない。"}, {"text": "赤ちゃん", "is_correct": false, "explanation": "「学校の赤ちゃん」は意味が通らない。"}], "explanations": {"改革": "学校の仕組みを改めることが始まったので「改革」が合う。", "天気": "天気が「始まった」とは言わない。", "机": "机が始まることはない。", "赤ちゃん": "「学校の赤ちゃん」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一冊の改革が始まった。", "explanation": "助数詞の誤り。改革は「冊」で数えない。"}, {"text": "改革を町が変わった。", "explanation": "助詞の誤り。原因を表すには「を」ではなく「のおかげで」などを使う。"}, {"text": "改革は明日始まった。", "explanation": "時制の誤り。「明日」と過去の「た」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bbd0a6-b886-4820-ab4a-1c60968d3863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warni