INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35333, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改革", "is_correct": true, "explanation": "「かいかく」と読む正解の語。"}, {"text": "価格", "is_correct": false, "explanation": "「かかく」と読み、物の値段という意味の別の語。"}, {"text": "外角", "is_correct": false, "explanation": "「がいかく」と読み、外側の角という意味の別の語。"}, {"text": "解約", "is_correct": false, "explanation": "「かいやく」と読み、約束や契約をやめることという意味の別の語。"}, {"text": "改札", "is_correct": false, "explanation": "「かいさつ」と読み、駅で切符を調べる所という意味の別の語。"}], "explanations": {"改革": "「かいかく」と読む正解の語。", "価格": "「かかく」と読み、物の値段という意味の別の語。", "外角": "「がいかく」と読み、外側の角という意味の別の語。", "解約": "「かいやく」と読み、約束や契約をやめることという意味の別の語。", "改札": "「かいさつ」と読み、駅で切符を調べる所という意味の別の語。"}, "sentence_index": null, "correct_answer": "改革"}, "level_3": {"options": [{"text": "改革", "is_correct": true, "explanation": "仕組みを新しく改めるのは簡単ではないので「改革」が合う。"}, {"text": "りんご", "is_correct": false, "explanation": "りんごが簡単ではない、は意味が通らない。"}, {"text": "青空", "is_correct": false, "explanation": "青空が簡単ではない、とは言わない。"}, {"text": "靴下", "is_correct": false, "explanation": "靴下が簡単ではない、は不自然。"}], "explanations": {"改革": "仕組みを新しく改めるのは簡単ではないので「改革」が合う。", "りんご": "りんごが簡単ではない、は意味が通らない。", "青空": "青空が簡単ではない、とは言わない。", "靴下": "靴下が簡単ではない、は不自然。"}, "sentence_index": 6, "correct_answer": "改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は改革を反対している。", "explanation": "助詞の誤り。「反対する」の相手には「に」を使う。"}, {"text": "父は三匹の改革に反対している。", "explanation": "助数詞の誤り。改革を「匹」で数えない。"}, {"text": "昨日、父は改革に反対するだろう。", "explanation": "時制の誤り。「昨日」と推量の未来表現は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bbd0a6-b886-4820-ab4a-1c60968d3863') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_w