INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35347, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "文章などを、いくつかに分けて並べた一つ一つの項目。", "primary_collocate": null, "pronunciation": "かじょう", "ipa": "kaʑoː", "syllable_count": 3, "sentences": [{"text": "規則は五つの箇条からできている。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "きそく いつ かじょう", "sentence_source": "generated"}, {"text": "大事な点を三つの箇条に分けた。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "だいじ てん みっ かじょう わ", "sentence_source": "generated"}, {"text": "この箇条をよく読んでください。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう よ", "sentence_source": "generated"}, {"text": "最初の箇条が一番大切だ。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "さいしょ かじょう いちばん たいせつ", "sentence_source": "generated"}, {"text": "約束を三つの箇条にまとめた。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "やくそく みっ かじょう", "sentence_source": "generated"}, {"text": "箇条ごとに意見を書いてね。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう いけん か", "sentence_source": "generated"}, {"text": "新しい箇条が一つ加わった。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "あたら かじょう ひと くわ", "sentence_source": "generated"}, {"text": "その箇条は少し分かりにくい。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう すこ わ", "sentence_source": "generated"}, {"text": "クラスのルールを箇条にして貼った。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう は", "sentence_source": "generated"}, {"text": "箇条の数を数えてみよう。", "target_word": "箇条", "complexity_tier": "T3", "furigana": "かじょう かず かぞ", "sentence_source": "generated"}], "morphological_forms": [{"form": "箇条書き", "label": "派生"}, {"form": "箇条書きにする", "label": "派生"}, {"form": "か条", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 文章を分けた一つ一つの項目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted fo