INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35364, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "一つの物や情報を、何人かで一緒に持ったり使ったりすること。", "primary_collocate": null, "pronunciation": "きょうゆう", "ipa": "kʲoːjɯː", "syllable_count": 4, "sentences": [{"text": "家族で一台の車を共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "かぞく いちだい くるま きょうゆう", "sentence_source": "generated"}, {"text": "みんなで情報を共有しよう。", "target_word": "共有", "complexity_tier": "T3", "furigana": "じょうほう きょうゆう", "sentence_source": "generated"}, {"text": "この部屋は三人で共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "へや さんにん きょうゆう", "sentence_source": "generated"}, {"text": "写真を友だちと共有した。", "target_word": "共有", "complexity_tier": "T3", "furigana": "しゃしん とも きょうゆう", "sentence_source": "generated"}, {"text": "共有のパソコンを使ってください。", "target_word": "共有", "complexity_tier": "T3", "furigana": "きょうゆう つか", "sentence_source": "generated"}, {"text": "ファイルの共有ができない。", "target_word": "共有", "complexity_tier": "T3", "furigana": "きょうゆう", "sentence_source": "generated"}, {"text": "台所はみんなで共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "だいどころ きょうゆう", "sentence_source": "generated"}, {"text": "考えを共有することが大切だ。", "target_word": "共有", "complexity_tier": "T3", "furigana": "かんが きょうゆう たいせつ", "sentence_source": "generated"}, {"text": "このノートはクラスで共有している。", "target_word": "共有", "complexity_tier": "T3", "furigana": "きょうゆう", "sentence_source": "generated"}, {"text": "予定を共有してもらえますか。", "target_word": "共有", "complexity_tier": "T3", "furigana": "よてい きょうゆう", "sentence_source": "generated"}], "morphological_forms": [{"form": "共有する", "label": "派生"}, {"form": "共有した", "label": "活用"}, {"form": "共有財産", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物や情報を複数で共に持つ・使うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted