INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35358, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医学", "is_correct": true, "explanation": "正解。読みは「いがく」。"}, {"text": "ごがく", "is_correct": false, "explanation": "読みは「語学」。「い」が「ご」に変わる一モーラ差。"}, {"text": "いやく", "is_correct": false, "explanation": "読みは「医薬」。「が」が「や」に変わる一モーラ差。"}, {"text": "いかく", "is_correct": false, "explanation": "読みは「威嚇」。「が」が「か」に変わる清濁の差。"}, {"text": "びがく", "is_correct": false, "explanation": "読みは「美学」。「い」が「び」に変わる一モーラ差。"}], "explanations": {"医学": "正解。読みは「いがく」。", "ごがく": "読みは「語学」。「い」が「ご」に変わる一モーラ差。", "いやく": "読みは「医薬」。「が」が「や」に変わる一モーラ差。", "いかく": "読みは「威嚇」。「が」が「か」に変わる清濁の差。", "びがく": "読みは「美学」。「い」が「び」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "医学"}, "level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "大学で学ぶ学問として自然に入る。"}, {"text": "窓", "is_correct": false, "explanation": "窓を大学で勉強するとは言わない。"}, {"text": "医者", "is_correct": false, "explanation": "医者は人であり、「勉強する」の対象にならない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は場所で、勉強する内容ではない。"}], "explanations": {"医学": "大学で学ぶ学問として自然に入る。", "窓": "窓を大学で勉強するとは言わない。", "医者": "医者は人であり、「勉強する」の対象にならない。", "病院": "病院は場所で、勉強する内容ではない。"}, "sentence_index": 0, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医学を食べて元気になった。", "explanation": "医学は学問で、食べ物ではない。"}, {"text": "医学が痛いので薬を飲んだ。", "explanation": "痛むのは体で、学問の医学ではない。"}, {"text": "この医学は甘くておいしい。", "explanation": "医学に味はない。学問を食べ物として誤用している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
