INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35358, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医学", "is_correct": true, "explanation": "正解。読みは「いがく」。"}, {"text": "ちがく", "is_correct": false, "explanation": "読みは「地学」。「いがく」と音が近いが別語。"}, {"text": "しがく", "is_correct": false, "explanation": "読みは「私学」。「いがく」と音が近いが別語。"}, {"text": "いがい", "is_correct": false, "explanation": "読みは「以外」。「いがく」と音が近いが別語。"}, {"text": "かがく", "is_correct": false, "explanation": "読みは「化学」。「いがく」と音が近いが別語。"}], "explanations": {"医学": "正解。読みは「いがく」。", "ちがく": "読みは「地学」。「いがく」と音が近いが別語。", "しがく": "読みは「私学」。「いがく」と音が近いが別語。", "いがい": "読みは「以外」。「いがく」と音が近いが別語。", "かがく": "読みは「化学」。「いがく」と音が近いが別語。"}, "sentence_index": null, "correct_answer": "医学"}, "level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "「医学の勉強」で学問の内容を表し、自然。"}, {"text": "机", "is_correct": false, "explanation": "机の勉強とは言わず不自然。"}, {"text": "電車", "is_correct": false, "explanation": "電車の勉強には時間がかかる、は文意が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "窓の勉強とは言わない。"}], "explanations": {"医学": "「医学の勉強」で学問の内容を表し、自然。", "机": "机の勉強とは言わず不自然。", "電車": "電車の勉強には時間がかかる、は文意が通らない。", "窓": "窓の勉強とは言わない。"}, "sentence_index": 6, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医学が転んでけがをした。", "explanation": "医学は学問で、転ぶことはない。"}, {"text": "医学を一匹飼っている。", "explanation": "医学は生き物ではない。"}, {"text": "医学で手を洗ってください。", "explanation": "医学は物ではないので手を洗う道具にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
