INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35359, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医学", "is_correct": true, "explanation": "正解。読みは「いがく」。"}, {"text": "かがく", "is_correct": false, "explanation": "読みは「化学」。「い」が「か」に変わる一モーラ差。"}, {"text": "いかく", "is_correct": false, "explanation": "読みは「威嚇」。「が」と「か」の清濁の差。"}, {"text": "ごがく", "is_correct": false, "explanation": "読みは「語学」。最初のモーラ「い」が「ご」に変わる。"}, {"text": "いやく", "is_correct": false, "explanation": "読みは「医薬」。二番目のモーラ「が」が「や」に変わる。"}], "explanations": {"医学": "正解。読みは「いがく」。", "かがく": "読みは「化学」。「い」が「か」に変わる一モーラ差。", "いかく": "読みは「威嚇」。「が」と「か」の清濁の差。", "ごがく": "読みは「語学」。最初のモーラ「い」が「ご」に変わる。", "いやく": "読みは「医薬」。二番目のモーラ「が」が「や」に変わる。"}, "sentence_index": null, "correct_answer": "医学"}, "level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "現代の学問として進歩するので自然。"}, {"text": "医者", "is_correct": false, "explanation": "医者は人で、「進歩している」の主語として不自然。"}, {"text": "病院", "is_correct": false, "explanation": "病院は建物で、学問の進歩とは言わない。"}, {"text": "患者", "is_correct": false, "explanation": "患者が進歩するとは言わない。"}], "explanations": {"医学": "現代の学問として進歩するので自然。", "医者": "医者は人で、「進歩している」の主語として不自然。", "病院": "病院は建物で、学問の進歩とは言わない。", "患者": "患者が進歩するとは言わない。"}, "sentence_index": 0, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医学を飲んで熱が下がった。", "explanation": "医学は学問で、飲むものではない。"}, {"text": "医学が熱を出して休んだ。", "explanation": "医学は人ではなく、熱を出さない。"}, {"text": "医学を二冊買った。", "explanation": "医学は学問で、冊で数える本ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
