INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35359, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医学", "is_correct": true, "explanation": "正解。読みは「いがく」。"}, {"text": "ちがく", "is_correct": false, "explanation": "読みは「地学」。「いがく」と音が近いが別語。"}, {"text": "しがく", "is_correct": false, "explanation": "読みは「私学」。「いがく」と音が近いが別語。"}, {"text": "いがい", "is_correct": false, "explanation": "読みは「意外」。「いがく」と音が近いが別語。"}, {"text": "いがた", "is_correct": false, "explanation": "読みは「鋳型」。「いがく」と音が近いが別語。"}], "explanations": {"医学": "正解。読みは「いがく」。", "ちがく": "読みは「地学」。「いがく」と音が近いが別語。", "しがく": "読みは「私学」。「いがく」と音が近いが別語。", "いがい": "読みは「意外」。「いがく」と音が近いが別語。", "いがた": "読みは「鋳型」。「いがく」と音が近いが別語。"}, "sentence_index": null, "correct_answer": "医学"}, "level_3": {"options": [{"text": "医学", "is_correct": true, "explanation": "昔の学問としての医学で治せなかった、で自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気で治すという意味にならない。"}, {"text": "机", "is_correct": false, "explanation": "机で病気を治すことはできない。"}, {"text": "音楽", "is_correct": false, "explanation": "「昔の音楽では治せなかった」は文意が通らない。"}], "explanations": {"医学": "昔の学問としての医学で治せなかった、で自然。", "天気": "天気で治すという意味にならない。", "机": "机で病気を治すことはできない。", "音楽": "「昔の音楽では治せなかった」は文意が通らない。"}, "sentence_index": 6, "correct_answer": "医学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医学によって窓を開けた。", "explanation": "医学は窓を開ける手段ではない。"}, {"text": "医学が朝ご飯を作った。", "explanation": "医学は人ではなく料理しない。"}, {"text": "医学を着て出かけた。", "explanation": "医学は服ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_bat