INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35361, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "書籍", "is_correct": true, "explanation": "正解。読みは「しょせき」。"}, {"text": "しょしき", "is_correct": false, "explanation": "読みは「書式」。「せ」が「し」に変わる一モーラ差。"}, {"text": "じょせき", "is_correct": false, "explanation": "読みは「除籍」。「しょ」が「じょ」に変わる清濁の差。"}, {"text": "しせき", "is_correct": false, "explanation": "読みは「史跡」。「しょ」が「し」に変わる一モーラ差。"}, {"text": "しょせい", "is_correct": false, "explanation": "読みは「処世」。「き」が「い」に変わる一モーラ差。"}], "explanations": {"書籍": "正解。読みは「しょせき」。", "しょしき": "読みは「書式」。「せ」が「し」に変わる一モーラ差。", "じょせき": "読みは「除籍」。「しょ」が「じょ」に変わる清濁の差。", "しせき": "読みは「史跡」。「しょ」が「し」に変わる一モーラ差。", "しょせい": "読みは「処世」。「き」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "書籍"}, "level_3": {"options": [{"text": "書籍", "is_correct": true, "explanation": "出版される本なので自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は出版されない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は出版されるものではない。"}, {"text": "机", "is_correct": false, "explanation": "机は出版されない。"}], "explanations": {"書籍": "出版される本なので自然。", "天気": "天気は出版されない。", "料理": "料理は出版されるものではない。", "机": "机は出版されない。"}, "sentence_index": 0, "correct_answer": "書籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は書籍を三匹書いている。", "explanation": "助数詞の誤り：書籍は「冊」で数える。"}, {"text": "書籍が歌を歌った。", "explanation": "書籍は物で、歌わない。"}, {"text": "書籍を焼いて食べた。", "explanation": "書籍は食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3df5712f-33d8-4848-b7bb-e9f929eb3bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
