INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35370, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の速さがもっと速くなること。", "primary_collocate": null, "pronunciation": "かそく", "ipa": "kasokɯ", "syllable_count": 3, "sentences": [{"text": "車が急に加速した。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "電車は駅を出て加速する。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "坂道で自転車が加速した。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "加速の感じが楽しかった。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "変化が加速している。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "ボールは落ちながら加速する。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "加速すると危ないよ。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "人口の減少が加速している。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "バイクの加速がすごい。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}, {"text": "彼は最後に加速して勝った。", "target_word": "加速", "complexity_tier": "T3", "furigana": "加速（かそく）", "sentence_source": "generated"}], "morphological_forms": [{"form": "加速する", "label": "派生"}, {"form": "加速度", "label": "派生"}, {"form": "急加速", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 速さがさらに増すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7647ac2f-1