INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の基準となる、ふつうの形や状態。", "primary_collocate": null, "pronunciation": "ひょうじゅん", "ipa": "çoːdʑɯɴ", "syllable_count": 4, "sentences": [{"text": "彼の身長は標準より高い。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "テストは標準の難しさだった。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "標準の体重を知りたい。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "これが標準のやり方です。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "彼の成績は標準以上だ。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "これが標準の大きさです。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "標準より少し安い値段だ。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "この町の気温は標準だ。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "標準から外れていても大丈夫。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}, {"text": "標準の量を食べよう。", "target_word": "標準", "complexity_tier": "T3", "furigana": "標準（ひょうじゅん）", "sentence_source": "generated"}], "morphological_forms": [{"form": "標準語", "label": "派生"}, {"form": "標準的", "label": "派生"}, {"form": "標準体重", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 基準となるふつうの形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-see