INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35365, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共有", "is_correct": true, "explanation": "正解。「共有」（きょうゆう）。"}, {"text": "教養", "is_correct": false, "explanation": "「教養」（きょうよう）。「ゆ」が「よ」になる一モーラ差。"}, {"text": "級友", "is_correct": false, "explanation": "「級友」（きゅうゆう）。「きょ」が「きゅ」になる一モーラ差。"}, {"text": "交友", "is_correct": false, "explanation": "「交友」（こうゆう）。「きょ」が「こ」になる一モーラ差。"}, {"text": "教諭", "is_correct": false, "explanation": "「教諭」（きょうゆ）。最後の長音がない長短の違い。"}], "explanations": {"共有": "正解。「共有」（きょうゆう）。", "教養": "「教養」（きょうよう）。「ゆ」が「よ」になる一モーラ差。", "級友": "「級友」（きゅうゆう）。「きょ」が「きゅ」になる一モーラ差。", "交友": "「交友」（こうゆう）。「きょ」が「こ」になる一モーラ差。", "教諭": "「教諭」（きょうゆ）。最後の長音がない長短の違い。"}, "sentence_index": null, "correct_answer": "共有"}, "level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "正解。文脈に合うのは「共有」。"}, {"text": "掃除", "is_correct": false, "explanation": "意味：写真を友達と掃除することはない。"}, {"text": "料理", "is_correct": false, "explanation": "意味：写真は料理できない。"}, {"text": "運動", "is_correct": false, "explanation": "連語：「写真を運動する」は言えない。"}], "explanations": {"共有": "正解。文脈に合うのは「共有」。", "掃除": "意味：写真を友達と掃除することはない。", "料理": "意味：写真は料理できない。", "運動": "連語：「写真を運動する」は言えない。"}, "sentence_index": 0, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "共有を一冊ください。", "explanation": "助数詞の誤り：「共有」は物ではなく数えられない。"}, {"text": "パソコンが友達を共有した。", "explanation": "助詞の混同：持つ人に「が」、物に「を」を使う。"}, {"text": "共有なパソコンを使っている。", "explanation": "品詞の誤り：名詞「共有」は「の」で修飾する。「な」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDE