INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35372, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "言語", "is_correct": true, "explanation": "正解。「言語」（げんご）。"}, {"text": "元号", "is_correct": false, "explanation": "「元号」（げんごう）。最後に長音がつく長短の違い。"}, {"text": "堅固", "is_correct": false, "explanation": "「堅固」（けんご）。「げ」が「け」になる清濁の違い。"}, {"text": "限度", "is_correct": false, "explanation": "「限度」（げんど）。「ご」が「ど」になる一モーラ差。"}], "explanations": {"言語": "正解。「言語」（げんご）。", "元号": "「元号」（げんごう）。最後に長音がつく長短の違い。", "堅固": "「堅固」（けんご）。「げ」が「け」になる清濁の違い。", "限度": "「限度」（げんど）。「ご」が「ど」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "言語"}, "level_3": {"options": [{"text": "言語", "is_correct": true, "explanation": "正解。文脈に合うのは「言語」。"}, {"text": "地球", "is_correct": false, "explanation": "意味：地球は一つしかない。"}, {"text": "太陽", "is_correct": false, "explanation": "意味：世界に太陽は多くない。"}, {"text": "月", "is_correct": false, "explanation": "意味：「世界には多くの月がある」は不自然。"}], "explanations": {"言語": "正解。文脈に合うのは「言語」。", "地球": "意味：地球は一つしかない。", "太陽": "意味：世界に太陽は多くない。", "月": "意味：「世界には多くの月がある」は不自然。"}, "sentence_index": 0, "correct_answer": "言語"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "言語を三匹学んだ。", "explanation": "助数詞の誤り：言語は「匹」で数えない。"}, {"text": "言語が学ぶのは楽しい。", "explanation": "助詞の混同：学ぶ対象は「を」で示す。"}, {"text": "言語するのは楽しい。", "explanation": "語法の誤り：「言語」は「する」をつけて動詞にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
