INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35374, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "標準", "is_correct": true, "explanation": "正解。「標準」（ひょうじゅん）。"}, {"text": "照準", "is_correct": false, "explanation": "「照準」（しょうじゅん）。「ひょ」が「しょ」になる一モーラ差。"}, {"text": "恭順", "is_correct": false, "explanation": "「恭順」（きょうじゅん）。「ひょ」が「きょ」になる一モーラ差。"}, {"text": "降順", "is_correct": false, "explanation": "「降順」（こうじゅん）。「ひょ」が「こ」になる一モーラ差。"}], "explanations": {"標準": "正解。「標準」（ひょうじゅん）。", "照準": "「照準」（しょうじゅん）。「ひょ」が「しょ」になる一モーラ差。", "恭順": "「恭順」（きょうじゅん）。「ひょ」が「きょ」になる一モーラ差。", "降順": "「降順」（こうじゅん）。「ひょ」が「こ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "標準"}, "level_3": {"options": [{"text": "標準", "is_correct": true, "explanation": "正解。文脈に合うのは「標準」。"}, {"text": "天気", "is_correct": false, "explanation": "意味：部品が天気に合うとは言わない。"}, {"text": "歴史", "is_correct": false, "explanation": "意味：部品が歴史に合うは不自然。"}, {"text": "料理", "is_correct": false, "explanation": "意味：部品と料理は関係がない。"}], "explanations": {"標準": "正解。文脈に合うのは「標準」。", "天気": "意味：部品が天気に合うとは言わない。", "歴史": "意味：部品が歴史に合うは不自然。", "料理": "意味：部品と料理は関係がない。"}, "sentence_index": 0, "correct_answer": "標準"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "標準を三匹作った。", "explanation": "助数詞の誤り：きまりは「匹」で数えない。"}, {"text": "世界が標準を合わせよう。", "explanation": "助詞の混同：「世界の標準に合わせよう」が正しい。"}, {"text": "標準な世界に合わせよう。", "explanation": "品詞の誤り：名詞「標準」は「の」で修飾する。「な」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeaaebd-38df-4ff1-af83-08e2166ad7d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
