INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35378, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いろいろな場所。あちこちの土地。", "primary_collocate": null, "pronunciation": "かくち", "ipa": "kakɯtɕi", "syllable_count": 3, "sentences": [{"text": "各地で雨が降っています。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かくち あめ ふ", "sentence_source": "generated"}, {"text": "祭りは日本の各地で行われる。", "target_word": "各地", "complexity_tier": "T3", "furigana": "まつ にほん かくち おこな", "sentence_source": "generated"}, {"text": "各地の料理を食べてみたい。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かくち りょうり た", "sentence_source": "generated"}, {"text": "父は仕事で各地を回っている。", "target_word": "各地", "complexity_tier": "T3", "furigana": "ちち しごと かくち まわ", "sentence_source": "generated"}, {"text": "各地から人が集まった。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かくち ひと あつ", "sentence_source": "generated"}, {"text": "各地の天気をニュースで見た。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かくち てんき み", "sentence_source": "generated"}, {"text": "このお茶は各地で人気がある。", "target_word": "各地", "complexity_tier": "T3", "furigana": "ちゃ かくち にんき", "sentence_source": "generated"}, {"text": "彼は世界各地を旅している。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かれ せかい かくち たび", "sentence_source": "generated"}, {"text": "各地に古いお寺が残っている。", "target_word": "各地", "complexity_tier": "T3", "furigana": "かくち ふる てら のこ", "sentence_source": "generated"}, {"text": "台風の被害が各地に出た。", "target_word": "各地", "complexity_tier": "T3", "furigana": "たいふう ひがい かくち で", "sentence_source": "generated"}], "morphological_forms": [{"form": "全国各地", "label": "派生"}, {"form": "世界各地", "label": "派生"}, {"form": "各地方", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | いろいろな土地やあちこちの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::j