INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35385, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある地域や集団で使われる、標準語と違う言葉。", "primary_collocate": null, "pronunciation": "ほうげん", "ipa": "hoːɡeɴ", "syllable_count": 4, "sentences": [{"text": "方言と標準語の違いを調べた。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん ひょうじゅんご ちが しら", "sentence_source": "generated"}, {"text": "日本には多くの方言がある。", "target_word": "方言", "complexity_tier": "T3", "furigana": "にほん おお ほうげん", "sentence_source": "generated"}, {"text": "方言は地域の文化の一つだ。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん ちいき ぶんか ひと", "sentence_source": "generated"}, {"text": "若い人は方言をあまり使わない。", "target_word": "方言", "complexity_tier": "T3", "furigana": "わか ひと ほうげん つか", "sentence_source": "generated"}, {"text": "方言が消えていくのは悲しい。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん き かな", "sentence_source": "generated"}, {"text": "先生は方言の研究をしている。", "target_word": "方言", "complexity_tier": "T3", "furigana": "せんせい ほうげん けんきゅう", "sentence_source": "generated"}, {"text": "方言の地図を授業で見た。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん ちず じゅぎょう み", "sentence_source": "generated"}, {"text": "この言葉は九州の方言だ。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ことば きゅうしゅう ほうげん", "sentence_source": "generated"}, {"text": "方言を守る活動が行われている。", "target_word": "方言", "complexity_tier": "T3", "furigana": "ほうげん まも かつどう おこな", "sentence_source": "generated"}, {"text": "同じ県でも方言は少し違う。", "target_word": "方言", "complexity_tier": "T3", "furigana": "おな けん ほうげん すこ ちが", "sentence_source": "generated"}], "morphological_forms": [{"form": "方言学", "label": "派生"}, {"form": "地方方言", "label": "派生"}, {"form": "方言差", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 地域や集団で使う標準語と違う言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '277d58e8-d9d9-4a40-95d5-8b782521f941') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35378, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各地", "is_correct": true, "explanation": "正解：「各地（かくち）」。"}, {"text": "各自", "is_correct": false, "explanation": "「各自（かくじ）」。「ち」と「じ」が違う一モーラ差。"}, {"text": "角度", "is_correct": false, "explanation": "「角度（かくど）」。「ち」と「ど」が違う一モーラ差。"}, {"text": "角煮", "is_correct": false, "explanation": "「角煮（かくに）」。「ち」と「に」が違う一モーラ差。"}, {"text": "隠し", "is_correct": false, "explanation": "「隠し（かくし）」。「ち」と「し」が違う一モーラ差。"}], "explanations": {"各地": "正解：「各地（かくち）」。", "各自": "「各自（かくじ）」。「ち」と「じ」が違う一モーラ差。", "角度": "「角度（かくど）」。「ち」と「ど」が違う一モーラ差。", "角煮": "「角煮（かくに）」。「ち」と「に」が違う一モーラ差。", "隠し": "「隠し（かくし）」。「ち」と「し」が違う一モーラ差。"}, "sentence_index": null, "correct_answer": "各地"}, "level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "家庭", "is_correct": false, "explanation": "意味：雨が降る広い範囲を表さない。"}, {"text": "室内", "is_correct": false, "explanation": "意味：室内では雨は降らない。"}, {"text": "場合", "is_correct": false, "explanation": "項構造：「場合で」は場所を示せない。"}], "explanations": {"各地": "文の意味に合う。", "家庭": "意味：雨が降る広い範囲を表さない。", "室内": "意味：室内では雨は降らない。", "場合": "項構造：「場合で」は場所を示せない。"}, "sentence_index": 0, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は各地を一冊回っている。", "explanation": "助数詞の誤り：場所に「冊」は使えない。"}, {"text": "父は仕事が各地で回っている。", "explanation": "助詞の混同：「仕事で各地を」が正しい。"}, {"text": "父は各地を回っていた明日。", "explanation": "語順の誤り：時の語「明日」の位置と時制が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = E