INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "この文で正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「行われる」は受身で目的語をとらない。"}, {"text": "が", "is_correct": false, "explanation": "主語は「祭り」なので「各地が」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向で、行事の場所には使えない。"}], "correct_answer": "で", "explanations": {"で": "この文で正しい助詞。", "を": "「行われる」は受身で目的語をとらない。", "が": "主語は「祭り」なので「各地が」は不自然。", "へ": "「へ」は移動の方向で、行事の場所には使えない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35378, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "各地", "is_correct": true, "explanation": "正解：「各地（かくち）」。"}, {"text": "隔離", "is_correct": false, "explanation": "「隔離（かくり）」。最後の「ち」が「り」になる。"}, {"text": "各位", "is_correct": false, "explanation": "「各位（かくい）」。最後の「ち」が「い」になる。"}, {"text": "閣議", "is_correct": false, "explanation": "「閣議（かくぎ）」。最後の「ち」が「ぎ」になる。"}], "explanations": {"各地": "正解：「各地（かくち）」。", "隔離": "「隔離（かくり）」。最後の「ち」が「り」になる。", "各位": "「各位（かくい）」。最後の「ち」が「い」になる。", "閣議": "「閣議（かくぎ）」。最後の「ち」が「ぎ」になる。"}, "sentence_index": null, "correct_answer": "各地"}, "level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "夜中", "is_correct": false, "explanation": "意味：時間を表し、人気のある場所にならない。"}, {"text": "台所", "is_correct": false, "explanation": "意味：お茶が人気になる広い範囲ではない。"}, {"text": "気分", "is_correct": false, "explanation": "連語：「気分で人気がある」は不自然。"}], "explanations": {"各地": "文の意味に合う。", "夜中": "意味：時間を表し、人気のある場所にならない。", "台所": "意味：お茶が人気になる広い範囲ではない。", "気分": "連語：「気分で人気がある」は不自然。"}, "sentence_index": 6, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の被害を各地に出た。", "explanation": "助詞の混同：「被害が」が正しい。"}, {"text": "台風の被害が各地に三本出た。", "explanation": "助数詞の誤り：被害に「本」は使えない。"}, {"text": "台風の被害が各地に出ている昨日。", "explanation": "アスペクトと語順の誤り：「昨日」と「ている」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このお茶は各地が人気がある。", "corrected_sentence": "このお茶は各地で人気がある。", "error_description": "場所を示すには「が」ではなく「で」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
