INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35380, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ばらばら", "is_correct": true, "explanation": "正解：「ばらばら（ばらばら）」。"}, {"text": "ぱらぱら", "is_correct": false, "explanation": "「ぱらぱら（ぱらぱら）」。「ば」が半濁音「ぱ」になる（二か所）。"}, {"text": "がらがら", "is_correct": false, "explanation": "「がらがら（がらがら）」。「ば」が「が」になる（二か所）。"}, {"text": "ばたばた", "is_correct": false, "explanation": "「ばたばた（ばたばた）」。「ら」が「た」になる（二か所）。"}], "explanations": {"ばらばら": "正解：「ばらばら（ばらばら）」。", "ぱらぱら": "「ぱらぱら（ぱらぱら）」。「ば」が半濁音「ぱ」になる（二か所）。", "がらがら": "「がらがら（がらがら）」。「ば」が「が」になる（二か所）。", "ばたばた": "「ばたばた（ばたばた）」。「ら」が「た」になる（二か所）。"}, "sentence_index": null, "correct_answer": "ばらばら"}, "level_3": {"options": [{"text": "ばらばら", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "意味：輝く様子で、壊れた状態ではない。"}, {"text": "ふわふわ", "is_correct": false, "explanation": "意味：柔らかい様子で、割れたお皿に合わない。"}, {"text": "にこにこ", "is_correct": false, "explanation": "連語：お皿が「にこにこになる」は不自然。"}], "explanations": {"ばらばら": "文の意味に合う。", "ぴかぴか": "意味：輝く様子で、壊れた状態ではない。", "ふわふわ": "意味：柔らかい様子で、割れたお皿に合わない。", "にこにこ": "連語：お皿が「にこにこになる」は不自然。"}, "sentence_index": 0, "correct_answer": "ばらばら"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "帰りはみんながばらばらをした。", "explanation": "助詞と動詞の誤り：「ばらばらだった」が正しい。"}, {"text": "帰りはばらばらにみんなだった。", "explanation": "語順の誤り：文の構造が壊れている。"}, {"text": "帰りはみんな一人のばらばらだった。", "explanation": "意味の誤り：「一人のばらばら」という言い方はない。「みんなばらばらだった」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
