INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35380, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ばらばら", "is_correct": true, "explanation": "正解：「ばらばら（ばらばら）」。"}, {"text": "ばりばり", "is_correct": false, "explanation": "「ばりばり（ばりばり）」。「ら」が「り」になる。"}, {"text": "ざらざら", "is_correct": false, "explanation": "「ざらざら（ざらざら）」。「ば」が「ざ」になる。"}, {"text": "だらだら", "is_correct": false, "explanation": "「だらだら（だらだら）」。「ば」が「だ」になる。"}], "explanations": {"ばらばら": "正解：「ばらばら（ばらばら）」。", "ばりばり": "「ばりばり（ばりばり）」。「ら」が「り」になる。", "ざらざら": "「ざらざら（ざらざら）」。「ば」が「ざ」になる。", "だらだら": "「だらだら（だらだら）」。「ば」が「だ」になる。"}, "sentence_index": null, "correct_answer": "ばらばら"}, "level_3": {"options": [{"text": "ばらばら", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "きらきら", "is_correct": false, "explanation": "意味：光る様子で、離れた状態ではない。"}, {"text": "どきどき", "is_correct": false, "explanation": "意味：心の様子で、人が離れることではない。"}, {"text": "ぺこぺこ", "is_correct": false, "explanation": "連語：「ぺこぺこになった」は駅で別れる意味にならない。"}], "explanations": {"ばらばら": "文の意味に合う。", "きらきら": "意味：光る様子で、離れた状態ではない。", "どきどき": "意味：心の様子で、人が離れることではない。", "ぺこぺこ": "連語：「ぺこぺこになった」は駅で別れる意味にならない。"}, "sentence_index": 6, "correct_answer": "ばらばら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達は卒業後ばらばらをした。", "explanation": "助詞の誤り：「ばらばらになった」が正しい。"}, {"text": "友達が卒業後をばらばらになった。", "explanation": "助詞の混同：「卒業後を」は不自然。"}, {"text": "友達は卒業後ばらばらになっている明日。", "explanation": "語順とアスペクトの誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
