INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35382, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "存在", "is_correct": true, "explanation": "正解：「存在（そんざい）」。"}, {"text": "損害", "is_correct": false, "explanation": "「損害（そんがい）」。「ざ」が「が」になる一モーラ差。"}, {"text": "尊大", "is_correct": false, "explanation": "「尊大（そんだい）」。「ざ」が「だ」になる一モーラ差。"}, {"text": "混在", "is_correct": false, "explanation": "「混在（こんざい）」。「そ」が「こ」になる一モーラ差。"}, {"text": "散財", "is_correct": false, "explanation": "「散財（さんざい）」。「そ」が「さ」になる一モーラ差。"}], "explanations": {"存在": "正解：「存在（そんざい）」。", "損害": "「損害（そんがい）」。「ざ」が「が」になる一モーラ差。", "尊大": "「尊大（そんだい）」。「ざ」が「だ」になる一モーラ差。", "混在": "「混在（こんざい）」。「そ」が「こ」になる一モーラ差。", "散財": "「散財（さんざい）」。「そ」が「さ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "存在"}, "level_3": {"options": [{"text": "存在", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "料理", "is_correct": false, "explanation": "意味：宇宙人の料理を信じるは不自然。"}, {"text": "天気", "is_correct": false, "explanation": "意味：宇宙人と天気は結びつかない。"}, {"text": "宿題", "is_correct": false, "explanation": "連語：「宿題を信じる」は不自然。"}], "explanations": {"存在": "文の意味に合う。", "料理": "意味：宇宙人の料理を信じるは不自然。", "天気": "意味：宇宙人と天気は結びつかない。", "宿題": "連語：「宿題を信じる」は不自然。"}, "sentence_index": 0, "correct_answer": "存在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔ここに村が一枚存在していた。", "explanation": "助数詞の誤り：村に「枚」は使えない。"}, {"text": "昔ここを村が存在していた。", "explanation": "助詞の混同：場所は「に」。"}, {"text": "昔ここに村が存在している明日。", "explanation": "時制と語順の誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ec7c9a3-4215-468d-a32f-27e00d710727') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDE