INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35406, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "思想", "is_correct": true, "explanation": "正解。「しそう」と読む。"}, {"text": "悲壮", "is_correct": false, "explanation": "「ひそう」で、「しそう」とは一つの音が違う。"}, {"text": "子息", "is_correct": false, "explanation": "「しそく」で、「しそう」とは一つの音が違う。"}, {"text": "地層", "is_correct": false, "explanation": "「ちそう」で、「しそう」とは一つの音が違う。"}, {"text": "思考", "is_correct": false, "explanation": "「しこう」で、「しそう」とは一つの音が違う。"}], "explanations": {"思想": "正解。「しそう」と読む。", "悲壮": "「ひそう」で、「しそう」とは一つの音が違う。", "子息": "「しそく」で、「しそう」とは一つの音が違う。", "地層": "「ちそう」で、「しそう」とは一つの音が違う。", "思考": "「しこう」で、「しそう」とは一つの音が違う。"}, "sentence_index": null, "correct_answer": "思想"}, "level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「新しい天気」とは言わず、社会を変えるものでもない。"}, {"text": "机", "is_correct": false, "explanation": "机が社会を変えたは不自然。"}, {"text": "靴", "is_correct": false, "explanation": "靴が社会を変えたは不自然。"}], "explanations": {"思想": "文の意味に合う。", "天気": "「新しい天気」とは言わず、社会を変えるものでもない。", "机": "机が社会を変えたは不自然。", "靴": "靴が社会を変えたは不自然。"}, "sentence_index": 6, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "思想を洗濯機で洗った。", "explanation": "思想は洗えない。"}, {"text": "思想がワンワンほえた。", "explanation": "思想は動物ではない。"}, {"text": "思想を一キロ買った。", "explanation": "思想は量って買えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb66ba43-c1c1-4003-a4f3-17222943c4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
