INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35410, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものの力や働きが、ほかのものにまで届いて影響を与えること。", "primary_collocate": "影響", "pronunciation": "およぼす", "ipa": "ojobosɯ", "syllable_count": 4, "sentences": [{"text": "天気は気分に影響を及ぼす。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "てんき きぶん えいきょう およぼす", "sentence_source": "generated"}, {"text": "寝不足は体に悪い影響を及ぼした。", "target_word": "及ぼし", "complexity_tier": "T3", "furigana": "ねぶそく からだ わるい えいきょう およぼし", "sentence_source": "generated"}, {"text": "彼の言葉が私に影響を及ぼしている。", "target_word": "及ぼし", "complexity_tier": "T3", "furigana": "かれ ことば わたし えいきょう およぼし", "sentence_source": "generated"}, {"text": "スマホは目に害を及ぼすことがある。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "め がい およぼす", "sentence_source": "generated"}, {"text": "友だちが及ぼす影響は大きい。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "とも およぼす えいきょう おお", "sentence_source": "generated"}, {"text": "台風は町に被害を及ぼした。", "target_word": "及ぼし", "complexity_tier": "T3", "furigana": "たいふう まち ひがい およぼし", "sentence_source": "generated"}, {"text": "音楽は心に良い効果を及ぼす。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "おんがく こころ よ こうか およぼす", "sentence_source": "generated"}, {"text": "ゲームが成績に影響を及ぼさないか心配だ。", "target_word": "及ぼさ", "complexity_tier": "T3", "furigana": "せいせき えいきょう およぼさ しんぱい", "sentence_source": "generated"}, {"text": "小さな行動でも周りに力を及ぼせる。", "target_word": "及ぼせる", "complexity_tier": "T3", "furigana": "ちい こうどう まわ ちから およぼせる", "sentence_source": "generated"}, {"text": "先生の考えが及ぼした変化に驚いた。", "target_word": "及ぼし", "complexity_tier": "T3", "furigana": "せんせい かんが およぼし へんか おどろ", "sentence_source": "generated"}], "morphological_forms": [{"form": "及ぼした", "label": "活用"}, {"form": "及ぼして", "label": "活用"}, {"form": "及ぼさない", "label": "活用"}, {"form": "及ぼせる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 他に影響や作用を与える", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d1260b-9557-43eb-8dbb-dacacb920243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35862, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音を使って楽しむもの。歌や楽器の演奏など。", "primary_collocate": null, "pronunciation": "おんがく", "ipa": "oŋɡakɯ", "syllable_count": 4, "sentences": [{"text": "私は音楽を聞くのが好きだ。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "わたし おんがく き す", "sentence_source": "generated"}, {"text": "音楽は毎日の楽しみです。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく まいにち たの", "sentence_source": "generated"}, {"text": "兄は部屋で音楽をかけている。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "あに へや おんがく", "sentence_source": "generated"}, {"text": "音楽の時間に歌を歌った。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく じかん うた うた", "sentence_source": "generated"}, {"text": "静かな音楽で心が落ち着く。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "しず おんがく こころ お つ", "sentence_source": "generated"}, {"text": "父は古い音楽をよく聞いている。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "ちち ふる おんがく き", "sentence_source": "generated"}, {"text": "音楽が流れると、みんな踊り出した。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく なが おど だ", "sentence_source": "generated"}, {"text": "姉は音楽の先生になりたい。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "あね おんがく せんせい", "sentence_source": "generated"}, {"text": "友だちと音楽について話した。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "とも おんがく はな", "sentence_source": "generated"}, {"text": "好きな音楽は何ですか。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "す おんがく なん", "sentence_source": "generated"}], "morphological_forms": [{"form": "音楽家", "label": "派生"}, {"form": "音楽室", "label": "派生"}, {"form": "音楽会", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 音を使って楽しむもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"