INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音を組み合わせて作られた、人を楽しませたり感動させたりする芸術。", "primary_collocate": null, "pronunciation": "おんがく", "ipa": "oŋɡakɯ", "syllable_count": 4, "sentences": [{"text": "音楽は国を越えて人をつなぐ。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく くに こ ひと", "sentence_source": "generated"}, {"text": "彼女は大学で音楽を学んでいる。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "かのじょ だいがく おんがく まな", "sentence_source": "generated"}, {"text": "この曲は日本の音楽の名作だ。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "きょく にほん おんがく めいさく", "sentence_source": "generated"}, {"text": "音楽には人を感動させる力がある。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく ひと かんどう ちから", "sentence_source": "generated"}, {"text": "彼は音楽で気持ちを表現する。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "かれ おんがく きも ひょうげん", "sentence_source": "generated"}, {"text": "音楽の歴史を調べてみた。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく れきし しら", "sentence_source": "generated"}, {"text": "祖父はクラシック音楽に詳しい。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "そふ おんがく くわ", "sentence_source": "generated"}, {"text": "映画の音楽が心に残っている。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "えいが おんがく こころ のこ", "sentence_source": "generated"}, {"text": "音楽と絵は似ているところがある。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "おんがく え に", "sentence_source": "generated"}, {"text": "将来は音楽を作る仕事がしたい。", "target_word": "音楽", "complexity_tier": "T3", "furigana": "しょうらい おんがく つく しごと", "sentence_source": "generated"}], "morphological_forms": [{"form": "音楽家", "label": "派生"}, {"form": "音楽的", "label": "派生"}, {"form": "音楽祭", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 音を組み合わせた芸術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d1260b-9557-43eb-8dbb-dacacb920243') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35864, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いっしょであること。みんなで同じことをすること。", "primary_collocate": null, "pronunciation": "とも", "ipa": "tomo", "syllable_count": 2, "sentences": [{"text": "家族と共に夕食を食べた。", "target_word": "共", "complexity_tier": "T3", "furigana": "かぞく とも ゆうしょく た", "sentence_source": "generated"}, {"text": "仲間と共に山に登った。", "target_word": "共", "complexity_tier": "T3", "furigana": "なかま とも やま のぼ", "sentence_source": "generated"}, {"text": "私たちは共に笑い、共に泣いた。", "target_word": "共", "complexity_tier": "T3", "furigana": "わたし とも わら とも な", "sentence_source": "generated"}, {"text": "犬と共に暮らすのは楽しい。", "target_word": "共", "complexity_tier": "T3", "furigana": "いぬ とも く たの", "sentence_source": "generated"}, {"text": "友だちと共に過ごした時間は宝物だ。", "target_word": "共", "complexity_tier": "T3", "furigana": "とも とも す じかん たからもの", "sentence_source": "generated"}, {"text": "先生と共に問題を考えた。", "target_word": "共", "complexity_tier": "T3", "furigana": "せんせい とも もんだい かんが", "sentence_source": "generated"}, {"text": "苦労を共にした友は大切だ。", "target_word": "共", "complexity_tier": "T3", "furigana": "くろう とも とも たいせつ", "sentence_source": "generated"}, {"text": "彼とは三年間、行動を共にした。", "target_word": "共", "complexity_tier": "T3", "furigana": "かれ さんねんかん こうどう とも", "sentence_source": "generated"}, {"text": "両親は共に働いている。", "target_word": "共", "complexity_tier": "T3", "furigana": "りょうしん とも はたら", "sentence_source": "generated"}, {"text": "姉と私は共に音楽が好きだ。", "target_word": "共", "complexity_tier": "T3", "furigana": "あね わたし とも おんがく す", "sentence_source": "generated"}], "morphological_forms": [{"form": "共に", "label": "派生"}, {"form": "共働き", "label": "派生"}, {"form": "共倒れ", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一緒に同じことをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted fo