INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35866, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かゆいところなどを、手や指のつめでこすること。", "primary_collocate": null, "pronunciation": "かく", "ipa": "kakɯ", "syllable_count": 2, "sentences": [{"text": "蚊に刺された所を掻く。", "target_word": "掻く", "complexity_tier": "T3", "furigana": "か さ ところ かく", "sentence_source": "generated"}, {"text": "弟は頭を掻いて笑った。", "target_word": "掻い", "complexity_tier": "T3", "furigana": "おとうと あたま かい わら", "sentence_source": "generated"}, {"text": "かゆくても掻いてはいけない。", "target_word": "掻い", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "猫が耳を後ろ足で掻いている。", "target_word": "掻い", "complexity_tier": "T3", "furigana": "ねこ みみ うし あし かい", "sentence_source": "generated"}, {"text": "背中を掻いてくれませんか。", "target_word": "掻い", "complexity_tier": "T3", "furigana": "せなか かい", "sentence_source": "generated"}, {"text": "掻きすぎて腕が赤くなった。", "target_word": "掻き", "complexity_tier": "T3", "furigana": "かき うで あか", "sentence_source": "generated"}, {"text": "寝ている間に顔を掻いたらしい。", "target_word": "掻い", "complexity_tier": "T3", "furigana": "ね あいだ かお かい", "sentence_source": "generated"}, {"text": "背中は手が届かなくて掻けない。", "target_word": "掻け", "complexity_tier": "T3", "furigana": "せなか て とど かけ", "sentence_source": "generated"}, {"text": "彼は困ると首を掻く。", "target_word": "掻く", "complexity_tier": "T3", "furigana": "かれ こま くび かく", "sentence_source": "generated"}, {"text": "犬が体を掻く音がする。", "target_word": "掻く", "complexity_tier": "T3", "furigana": "いぬ からだ かく おと", "sentence_source": "generated"}], "morphological_forms": [{"form": "掻いた", "label": "活用"}, {"form": "掻いて", "label": "活用"}, {"form": "掻かない", "label": "活用"}, {"form": "掻ける", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 指のつめで体をこする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sen