INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35410, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "正解：「およぼす」。"}, {"text": "泳がす", "is_correct": false, "explanation": "「およがす」。三つ目のモーラ「ぼ」が「が」に変わる一モーラ差。"}, {"text": "滅ぼす", "is_correct": false, "explanation": "「ほろぼす」。「お」が「ほ」、「よ」が「ろ」に変わる。後半「ぼす」が同じで聞き違えやすい。"}, {"text": "遊ばす", "is_correct": false, "explanation": "「あそばす」。「およぼす」と後半「ぼす／ばす」が似ている。"}], "explanations": {"及ぼす": "正解：「およぼす」。", "泳がす": "「およがす」。三つ目のモーラ「ぼ」が「が」に変わる一モーラ差。", "滅ぼす": "「ほろぼす」。「お」が「ほ」、「よ」が「ろ」に変わる。後半「ぼす」が同じで聞き違えやすい。", "遊ばす": "「あそばす」。「およぼす」と後半「ぼす／ばす」が似ている。"}, "sentence_index": null, "correct_answer": "及ぼす"}, "level_3": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "「影響を及ぼす」で、天気が気分に作用することを表す。"}, {"text": "隠す", "is_correct": false, "explanation": "意味：影響を隠すのは天気の働きではない。"}, {"text": "払う", "is_correct": false, "explanation": "連語：「影響を払う」とは言わない。"}, {"text": "拾う", "is_correct": false, "explanation": "意味：影響を拾うという表現は成り立たない。"}], "explanations": {"及ぼす": "「影響を及ぼす」で、天気が気分に作用することを表す。", "隠す": "意味：影響を隠すのは天気の働きではない。", "払う": "連語：「影響を払う」とは言わない。", "拾う": "意味：影響を拾うという表現は成り立たない。"}, "sentence_index": 0, "correct_answer": "及ぼす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "スマホは目を害に及ぼすことがある。", "explanation": "助詞の混同：「目に害を及ぼす」が正しい。"}, {"text": "スマホは目に害を及ぼしてあることがある。", "explanation": "アスペクトの誤り：「てある」は使えない。"}, {"text": "目に害をスマホは及ぼすことがあるでした。", "explanation": "語順と活用が崩れていて不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931b00e6-ab0e-4a18-aa87-c90e02f05599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
