INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35410, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "正解：「およぼす」。"}, {"text": "及ぶ", "is_correct": false, "explanation": "「およぶ」。語末「ぼす」が「ぶ」になる。"}, {"text": "伸ばす", "is_correct": false, "explanation": "「のばす」。「およぼ」が「のば」に変わり、「す」が同じ。"}, {"text": "汚す", "is_correct": false, "explanation": "「よごす」。「よ」と「す」が共通で聞き違えやすい。"}], "explanations": {"及ぼす": "正解：「およぼす」。", "及ぶ": "「およぶ」。語末「ぼす」が「ぶ」になる。", "伸ばす": "「のばす」。「およぼ」が「のば」に変わり、「す」が同じ。", "汚す": "「よごす」。「よ」と「す」が共通で聞き違えやすい。"}, "sentence_index": null, "correct_answer": "及ぼす"}, "level_3": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "「効果を及ぼす」で、音楽が心に働きかけることを表す。"}, {"text": "盗む", "is_correct": false, "explanation": "意味：効果を盗むという働きは文脈に合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "連語：「効果を運ぶ」とは言わない。"}, {"text": "落とす", "is_correct": false, "explanation": "意味：良い効果を落とすでは逆の意味になる。"}], "explanations": {"及ぼす": "「効果を及ぼす」で、音楽が心に働きかけることを表す。", "盗む": "意味：効果を盗むという働きは文脈に合わない。", "運ぶ": "連語：「効果を運ぶ」とは言わない。", "落とす": "意味：良い効果を落とすでは逆の意味になる。"}, "sentence_index": 6, "correct_answer": "及ぼす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の考えを及ぼした変化に驚いた。", "explanation": "助詞の混同：連体修飾の主語は「が」か「の」。"}, {"text": "先生の考えが及ぼさせた変化に驚いた。", "explanation": "活用の誤り：「及ぼす」に使役「させ」は付けない。"}, {"text": "変化に先生の考えが驚いた及ぼした。", "explanation": "語順の誤り：述語の順序が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931b00e6-ab0e-4a18-aa87-c90e02f05599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35410, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちを及ぼす影響は大きい。", "corrected_sentence": "友だちが及ぼす影響は大きい。", "error_description": "助詞の混同：「及ぼす」の主体は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "及ぼさ", "is_correct": true, "explanation": "「ない」に続くのは未然形「及ぼさ」。"}, {"text": "及ぼし", "is_correct": false, "explanation": "連用形は「ない」に続かない。"}, {"text": "及ぼす", "is_correct": false, "explanation": "終止形に「ない」は付かない。"}, {"text": "及ぼそ", "is_correct": false, "explanation": "意向形の語幹で「ない」には続かない。"}], "correct_form": "及ぼさ", "base_form": "及ぼす", "form_label": "未然形（ない形）", "sentence_index": 7, "explanations": {"及ぼさ": "「ない」に続くのは未然形「及ぼさ」。", "及ぼし": "連用形は「ない」に続かない。", "及ぼす": "終止形に「ない」は付かない。", "及ぼそ": "意向形の語幹で「ない」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931b00e6-ab0e-4a18-aa87-c90e02f05599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
