INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35867, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "掻く", "is_correct": true, "explanation": "正解：「かく」。"}, {"text": "家具", "is_correct": false, "explanation": "「かぐ」。二つ目のモーラ「く」が濁って「ぐ」になる清濁の対立。"}, {"text": "柿", "is_correct": false, "explanation": "「かき」。二つ目のモーラ「く」が「き」に変わる一モーラ差。"}, {"text": "傘", "is_correct": false, "explanation": "「かさ」。二つ目のモーラ「く」が「さ」に変わる一モーラ差。"}, {"text": "額", "is_correct": false, "explanation": "「がく」。最初のモーラ「か」が濁って「が」になる清濁の対立。"}, {"text": "幕", "is_correct": false, "explanation": "「まく」。最初のモーラ「か」が「ま」に変わる一モーラ差。"}], "explanations": {"掻く": "正解：「かく」。", "家具": "「かぐ」。二つ目のモーラ「く」が濁って「ぐ」になる清濁の対立。", "柿": "「かき」。二つ目のモーラ「く」が「き」に変わる一モーラ差。", "傘": "「かさ」。二つ目のモーラ「く」が「さ」に変わる一モーラ差。", "額": "「がく」。最初のモーラ「か」が濁って「が」になる清濁の対立。", "幕": "「まく」。最初のモーラ「か」が「ま」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "掻く"}, "level_3": {"options": [{"text": "掻く", "is_correct": true, "explanation": "道具や手で雪をかき寄せてどける動作。"}, {"text": "食べる", "is_correct": false, "explanation": "意味：家の前の雪を食べるのは不自然。"}, {"text": "売る", "is_correct": false, "explanation": "意味：朝早く雪を売るのは文脈に合わない。"}, {"text": "飲む", "is_correct": false, "explanation": "項構造：雪は飲むものではない。"}], "explanations": {"掻く": "道具や手で雪をかき寄せてどける動作。", "食べる": "意味：家の前の雪を食べるのは不自然。", "売る": "意味：朝早く雪を売るのは文脈に合わない。", "飲む": "項構造：雪は飲むものではない。"}, "sentence_index": 0, "correct_answer": "掻く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父はスコップに雪を掻いている。", "explanation": "助詞の混同：道具は「で」で示す。"}, {"text": "父はスコップで雪を掻かれている。", "explanation": "態の誤り：父が自分で掻くので受身は使えない。"}, {"text": "雪をスコップ父はで掻いている。", "explanation": "語順の誤り：助詞の位置が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '931b00e6-ab0e-4a18-aa87-c90e02f05599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
