INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35868, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少し", "is_correct": true, "explanation": "正解。「すこし」と読む対象語。"}, {"text": "みこし", "is_correct": false, "explanation": "「みこし」と読む。最初のモーラ「す」が「み」に変わる一モーラ差。"}, {"text": "すまし", "is_correct": false, "explanation": "「すまし」と読む。二番目のモーラ「こ」が「ま」に変わる一モーラ差。"}, {"text": "透かし", "is_correct": false, "explanation": "「すかし」と読む。二番目のモーラ「こ」が「か」に変わる一モーラ差。"}, {"text": "お越し", "is_correct": false, "explanation": "「おこし」と読む。最初のモーラ「す」が「お」に変わる一モーラ差。"}], "explanations": {"少し": "正解。「すこし」と読む対象語。", "みこし": "「みこし」と読む。最初のモーラ「す」が「み」に変わる一モーラ差。", "すまし": "「すまし」と読む。二番目のモーラ「こ」が「ま」に変わる一モーラ差。", "透かし": "「すかし」と読む。二番目のモーラ「こ」が「か」に変わる一モーラ差。", "お越し": "「おこし」と読む。最初のモーラ「す」が「お」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "少し"}, "level_3": {"options": [{"text": "少し", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "全然", "is_correct": false, "explanation": "連語：「全然」は否定の文と結びつくので、「飲んでください」には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」は「〜ない」と使う語で、お願いの文には合わない。"}, {"text": "さっき", "is_correct": false, "explanation": "アスペクト：過去を表す「さっき」は、これからのお願いと合わない。"}], "explanations": {"少し": "正解。文脈に合う。", "全然": "連語：「全然」は否定の文と結びつくので、「飲んでください」には合わない。", "決して": "連語：「決して」は「〜ない」と使う語で、お願いの文には合わない。", "さっき": "アスペクト：過去を表す「さっき」は、これからのお願いと合わない。"}, "sentence_index": 0, "correct_answer": "少し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本語が少しを話せます。", "explanation": "助詞の混同：副詞「少し」に「を」は付けない。"}, {"text": "日本語が少しも話せます。", "explanation": "呼応の誤り：「少しも」は否定と使う。肯定の「話せます」とは結びつかない。"}, {"text": "日本語が話せます少し。", "explanation": "語順の誤り：副詞「少し」が文の最後に来ている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_ver