INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35868, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少し", "is_correct": true, "explanation": "正解。「すこし」と読む対象語。"}, {"text": "過ごし", "is_correct": false, "explanation": "「すごし」と読む。二拍目の「こ」が濁って「ご」になった違い。"}, {"text": "寿司", "is_correct": false, "explanation": "「すし」と読む。真ん中の「こ」が抜けた形。"}, {"text": "腰", "is_correct": false, "explanation": "「こし」と読む。語頭の「す」が抜けた形。"}], "explanations": {"少し": "正解。「すこし」と読む対象語。", "過ごし": "「すごし」と読む。二拍目の「こ」が濁って「ご」になった違い。", "寿司": "「すし」と読む。真ん中の「こ」が抜けた形。", "腰": "「こし」と読む。語頭の「す」が抜けた形。"}, "sentence_index": null, "correct_answer": "少し"}, "level_3": {"options": [{"text": "少し", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」は否定と結びつき、「遠いです」とは言えない。"}, {"text": "めったに", "is_correct": false, "explanation": "連語：「めったに」は「〜ない」と使うので合わない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "意味：動きの速さを表す語で、距離の程度には使えない。"}], "explanations": {"少し": "正解。文脈に合う。", "決して": "連語：「決して」は否定と結びつき、「遠いです」とは言えない。", "めったに": "連語：「めったに」は「〜ない」と使うので合わない。", "ゆっくり": "意味：動きの速さを表す語で、距離の程度には使えない。"}, "sentence_index": 6, "correct_answer": "少し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "少しが間、外で遊んだ。", "explanation": "助詞の混同：「少しの間」の「の」を「が」にしている。"}, {"text": "少しな間、外で遊んだ。", "explanation": "接続の誤り：「少し」が名詞を修飾するときは「の」を使う。「少しな」とは言わない。"}, {"text": "外で遊んだ、少しの間に間。", "explanation": "語順の誤り：時を表す語句の位置がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35868, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少しも間、外で遊んだ。", "corrected_sentence": "少しの間、外で遊んだ。", "error_description": "助詞の誤り：「少し」が名詞「間」を修飾するには「の」を使う。「少しも」は否定と使う語。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
