INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35874, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "より", "is_correct": true, "explanation": "正解。「より」と読む対象語。"}, {"text": "鳥", "is_correct": false, "explanation": "「とり」と読む。最初のモーラ「よ」が「と」に変わる一モーラ差。"}, {"text": "夜", "is_correct": false, "explanation": "「よる」と読む。二番目のモーラ「り」が「る」に変わる一モーラ差。"}, {"text": "横", "is_correct": false, "explanation": "「よこ」と読む。二番目のモーラ「り」が「こ」に変わる一モーラ差。"}, {"text": "栗", "is_correct": false, "explanation": "「くり」と読む。最初のモーラ「よ」が「く」に変わる一モーラ差。"}, {"text": "嫁", "is_correct": false, "explanation": "「よめ」と読む。二番目のモーラ「り」が「め」に変わる一モーラ差。"}], "explanations": {"より": "正解。「より」と読む対象語。", "鳥": "「とり」と読む。最初のモーラ「よ」が「と」に変わる一モーラ差。", "夜": "「よる」と読む。二番目のモーラ「り」が「る」に変わる一モーラ差。", "横": "「よこ」と読む。二番目のモーラ「り」が「こ」に変わる一モーラ差。", "栗": "「くり」と読む。最初のモーラ「よ」が「く」に変わる一モーラ差。", "嫁": "「よめ」と読む。二番目のモーラ「り」が「め」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "より"}, "level_3": {"options": [{"text": "より", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」は否定と結びつき、「良い方法を考えよう」には合わない。"}, {"text": "めったに", "is_correct": false, "explanation": "連語：「めったに」は「〜ない」と使う語で、ここでは使えない。"}, {"text": "さっき", "is_correct": false, "explanation": "アスペクト：過去の時を表し、これからの「考えよう」と合わない。"}], "explanations": {"より": "正解。文脈に合う。", "決して": "連語：「決して」は否定と結びつき、「良い方法を考えよう」には合わない。", "めったに": "連語：「めったに」は「〜ない」と使う語で、ここでは使えない。", "さっき": "アスペクト：過去の時を表し、これからの「考えよう」と合わない。"}, "sentence_index": 0, "correct_answer": "より"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店はよりに安くなった。", "explanation": "助詞の誤り：副詞「より」に「に」は付けない。"}, {"text": "この店はより安いをなった。", "explanation": "助詞の混同：「安くなった」とすべきところに「を」を入れている。"}, {"text": "この店は安くなったより。", "explanation": "語順の誤り：「より」は形容詞の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "よりの多くの人に読んでほしい。", "corrected_sentence": "より多くの人に読んでほしい。", "error_description": "助詞の誤り：副詞「より」に「の」は付かない。「より多くの」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
