INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35874, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "より", "is_correct": true, "explanation": "正解。「より」と読む対象語。"}, {"text": "森", "is_correct": false, "explanation": "「もり」と読む。語頭の「よ」が「も」になった一モーラ違い。"}, {"text": "百合", "is_correct": false, "explanation": "「ゆり」と読む。語頭の「よ」が「ゆ」になった一モーラ違い。"}, {"text": "読み", "is_correct": false, "explanation": "「よみ」と読む。二拍目の「り」が「み」になった一モーラ違い。"}, {"text": "蟻", "is_correct": false, "explanation": "「あり」と読む。語頭の「よ」が「あ」になった一モーラ違い。"}, {"text": "よそ", "is_correct": false, "explanation": "「よそ」と読む。二拍目の「り」が「そ」になった一モーラ違い。"}], "explanations": {"より": "正解。「より」と読む対象語。", "森": "「もり」と読む。語頭の「よ」が「も」になった一モーラ違い。", "百合": "「ゆり」と読む。語頭の「よ」が「ゆ」になった一モーラ違い。", "読み": "「よみ」と読む。二拍目の「り」が「み」になった一モーラ違い。", "蟻": "「あり」と読む。語頭の「よ」が「あ」になった一モーラ違い。", "よそ": "「よそ」と読む。二拍目の「り」が「そ」になった一モーラ違い。"}, "sentence_index": null, "correct_answer": "より"}, "level_3": {"options": [{"text": "より", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "ちっとも", "is_correct": false, "explanation": "連語：「ちっとも」は否定の文で使うので「便利になっている」に合わない。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」も否定と結びつく語で、ここには入らない。"}, {"text": "かつて", "is_correct": false, "explanation": "アスペクト：昔のことを表すので、今の変化「なっている」と合わない。"}], "explanations": {"より": "正解。文脈に合う。", "ちっとも": "連語：「ちっとも」は否定の文で使うので「便利になっている」に合わない。", "決して": "連語：「決して」も否定と結びつく語で、ここには入らない。", "かつて": "アスペクト：昔のことを表すので、今の変化「なっている」と合わない。"}, "sentence_index": 6, "correct_answer": "より"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "よりの強いチームを作りたい。", "explanation": "助詞の誤り：副詞「より」は「の」を介さず形容詞を直接修飾する。"}, {"text": "より強いチームに作りたい。", "explanation": "助詞の混同：作るものは「を」で表す。"}, {"text": "チームをより作りたい強い。", "explanation": "語順の誤り：「より」と「強い」が離れて、文がこわれている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町はよりの便利になっている。", "corrected_sentence": "町はより便利になっている。", "error_description": "助詞の誤り：副詞「より」に「の」は付かない。「より便利に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
