INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35876, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "良く", "is_correct": true, "explanation": "正解。「よく」と読む対象語。"}, {"text": "奥", "is_correct": false, "explanation": "「おく」と読む。最初のモーラ「よ」が「お」に変わる一モーラ差。"}, {"text": "夜", "is_correct": false, "explanation": "「よる」と読む。二番目のモーラ「く」が「る」に変わる一モーラ差。"}, {"text": "横", "is_correct": false, "explanation": "「よこ」と読む。二番目のモーラ「く」が「こ」に変わる一モーラ差。"}, {"text": "菊", "is_correct": false, "explanation": "「きく」と読む。最初のモーラ「よ」が「き」に変わる一モーラ差。"}, {"text": "楽", "is_correct": false, "explanation": "「らく」と読む。最初のモーラ「よ」が「ら」に変わる一モーラ差。"}], "explanations": {"良く": "正解。「よく」と読む対象語。", "奥": "「おく」と読む。最初のモーラ「よ」が「お」に変わる一モーラ差。", "夜": "「よる」と読む。二番目のモーラ「く」が「る」に変わる一モーラ差。", "横": "「よこ」と読む。二番目のモーラ「く」が「こ」に変わる一モーラ差。", "菊": "「きく」と読む。最初のモーラ「よ」が「き」に変わる一モーラ差。", "楽": "「らく」と読む。最初のモーラ「よ」が「ら」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "良く"}, "level_3": {"options": [{"text": "良く", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "意味：速さを表す語で、テストの出来ばえを表せない。"}, {"text": "めったに", "is_correct": false, "explanation": "連語：「めったに」は否定と使うので「できました」に合わない。"}, {"text": "うっかり", "is_correct": false, "explanation": "意味：不注意を表し、「できました」と意味がぶつかる。"}], "explanations": {"良く": "正解。文脈に合う。", "ゆっくり": "意味：速さを表す語で、テストの出来ばえを表せない。", "めったに": "連語：「めったに」は否定と使うので「できました」に合わない。", "うっかり": "意味：不注意を表し、「できました」と意味がぶつかる。"}, "sentence_index": 0, "correct_answer": "良く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この絵が良くを描けている。", "explanation": "助詞の混同：副詞「良く」に「を」は付かない。"}, {"text": "この絵は良い描けている。", "explanation": "活用の誤り：動詞を修飾するには連用形「良く」を使う。「良い」は名詞を修飾する形。"}, {"text": "この絵は描けて良くいる。", "explanation": "語順の誤り：「良く」が「描けて」と「いる」の間に入っている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
