INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35876, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪く", "is_correct": true, "explanation": "「良く（うまく、好ましく）」の反対で、うまくいかないようす。"}, {"text": "高く", "is_correct": false, "explanation": "高さを表す語で、「良く」の反対ではない。"}, {"text": "早く", "is_correct": false, "explanation": "時間の早さを表し、反対の関係にない。"}, {"text": "強く", "is_correct": false, "explanation": "力の強さを表し、反対の関係にない。"}], "correct_answer": "悪く", "explanations": {"悪く": "「良く（うまく、好ましく）」の反対で、うまくいかないようす。", "高く": "高さを表す語で、「良く」の反対ではない。", "早く": "時間の早さを表し、反対の関係にない。", "強く": "力の強さを表し、反対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35876, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "良く", "is_correct": true, "explanation": "正解。「よく」と読む対象語。"}, {"text": "肉", "is_correct": false, "explanation": "「にく」と読む。語頭の「よ」が「に」になった一モーラ違い。"}, {"text": "億", "is_correct": false, "explanation": "「おく」と読む。語頭の「よ」が「お」になった一モーラ違い。"}, {"text": "福", "is_correct": false, "explanation": "「ふく」と読む。語頭の「よ」が「ふ」になった一モーラ違い。"}, {"text": "夜", "is_correct": false, "explanation": "「よる」と読む。二拍目の「く」が「る」になった一モーラ違い。"}], "explanations": {"良く": "正解。「よく」と読む対象語。", "肉": "「にく」と読む。語頭の「よ」が「に」になった一モーラ違い。", "億": "「おく」と読む。語頭の「よ」が「お」になった一モーラ違い。", "福": "「ふく」と読む。語頭の「よ」が「ふ」になった一モーラ違い。", "夜": "「よる」と読む。二拍目の「く」が「る」になった一モーラ違い。"}, "sentence_index": null, "correct_answer": "良く"}, "level_3": {"options": [{"text": "良く", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "古く", "is_correct": false, "explanation": "意味：成績は古くなるものではないので、意味が合わない。"}, {"text": "重く", "is_correct": false, "explanation": "意味：重さは成績に使えない。"}, {"text": "多く", "is_correct": false, "explanation": "連語：「成績が多くなる」とは言わず、結びつきが不自然。"}], "explanations": {"良く": "正解。文脈に合う。", "古く": "意味：成績は古くなるものではないので、意味が合わない。", "重く": "意味：重さは成績に使えない。", "多く": "連語：「成績が多くなる」とは言わず、結びつきが不自然。"}, "sentence_index": 6, "correct_answer": "良く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "気分を良くなりました。", "explanation": "助詞の混同：「なる」の主語は「が」で表す。"}, {"text": "気分が良くなっていました昨日から今。", "explanation": "語順の誤り：時の語句が文の後ろに崩れて並んでいる。"}, {"text": "気分が良いなりました。", "explanation": "活用の誤り：「なる」の前は連用形「良く」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
