INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35880, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "今", "is_correct": true, "explanation": "正解。「いま」と読む対象語。"}, {"text": "島", "is_correct": false, "explanation": "「しま」と読む。最初のモーラ「い」が「し」に変わる一モーラ差。"}, {"text": "暇", "is_correct": false, "explanation": "「ひま」と読む。最初のモーラ「い」が「ひ」に変わる一モーラ差。"}, {"text": "犬", "is_correct": false, "explanation": "「いぬ」と読む。二番目のモーラ「ま」が「ぬ」に変わる一モーラ差。"}, {"text": "芋", "is_correct": false, "explanation": "「いも」と読む。二番目のモーラ「ま」が「も」に変わる一モーラ差。"}, {"text": "熊", "is_correct": false, "explanation": "「くま」と読む。最初のモーラ「い」が「く」に変わる一モーラ差。"}], "explanations": {"今": "正解。「いま」と読む対象語。", "島": "「しま」と読む。最初のモーラ「い」が「し」に変わる一モーラ差。", "暇": "「ひま」と読む。最初のモーラ「い」が「ひ」に変わる一モーラ差。", "犬": "「いぬ」と読む。二番目のモーラ「ま」が「ぬ」に変わる一モーラ差。", "芋": "「いも」と読む。二番目のモーラ「ま」が「も」に変わる一モーラ差。", "熊": "「くま」と読む。最初のモーラ「い」が「く」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "今"}, "level_3": {"options": [{"text": "今", "is_correct": true, "explanation": "正解。文脈に合う。"}, {"text": "昨日", "is_correct": false, "explanation": "アスペクト：過去の日なので、「何時ですか」という今の質問に合わない。"}, {"text": "昔", "is_correct": false, "explanation": "アスペクト：ずっと前のことで、現在形の質問と合わない。"}, {"text": "机", "is_correct": false, "explanation": "意味：物の名前で、時を表さない。"}], "explanations": {"今": "正解。文脈に合う。", "昨日": "アスペクト：過去の日なので、「何時ですか」という今の質問に合わない。", "昔": "アスペクト：ずっと前のことで、現在形の質問と合わない。", "机": "意味：物の名前で、時を表さない。"}, "sentence_index": 0, "correct_answer": "今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今が気持ちを話してください。", "explanation": "助詞の混同：「今の気持ち」の「の」を「が」にしている。"}, {"text": "今な気持ちを話してください。", "explanation": "接続の誤り：名詞「今」が名詞を修飾するときは「の」を使う。「今な」とは言わない。"}, {"text": "気持ちを今の話してください。", "explanation": "語順の誤り：「今の」が「気持ち」から離れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab670d18-ab6f-4e45-acad-d88e89f55e8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLU